quests[29161] = { id = 29161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bären da in den Bäumen", description = "Oh, Himbeeren! Wir hatten gerade das letzte Bärenjunge aus den Baumwipfeln gerettet, da kam das Feuer zurück und hat sie wieder verschreckt!\n\nIch weiß nicht, ob Ihr es schon wusstet, aber Babybären sind kostbar und weich.\n\nGeht zum Rauschenden Hain, weit im Nordwesten. Klettert auf die Bäume, schnappt Euch die Bärenjungen und werft sie - vorsichtig! - zu dem weichen Ziel in der Mitte des Hains.\n\n<Ohne Vorwarnung reißt Mylune Euch plötzlich an ihre Brust und beginnt zu schluchzen.>\n\nKleine B-b-b-b-Bärenbabies! Rettet sie, {name}!", sourceObjective = "Erklettert die Bäume im Rauschenden Hain, schnappt Euch gestrandete Hyjalbärenjunge und werft sie dann von den Baumwipfeln aus zum weichen Ziel. Das Ganze ist absolut sicher.", completion = "<Mylunes Gedanken schallen durch Euren Geist, zusammen mit ungebetenen Bildern von Blumen und Eichhörnchen.>\n\nOh, Ihr habt es geschafft, {name}! Die Babybären sind so glücklich.\n\nSo langsam habe ich das Gefühl, dass sie absichtlich damit angefangen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29162] = { id = 29162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Natur", description = "<Mylunes Stimme erklingt in Eurem Kopf wie das Geräusch von zwitschernden Vögeln.>\n\nIch liebe alle Wesen des Waldes, sogar Spinnen, obwohl sie eklig sind. Aber die Spinnen aus den Feuerlanden, die sind schlimmer als bloß eklig. Die brennen und sie gehören nicht hierher.\n\nFindet das Feuerportal im westlichen Teil des Geheilten Hyjal und benutzt den Edelstein, den ich Euch zuvor gegeben habe, um es zu öffnen. Wenn eine Feuerspinne rauskommt, dann tretet auf sie drauf! Es sei denn natürlich, sie ist groß. Dann macht irgendwas, was Ihr als {class} halt so macht.\n\nOh, und benutzt den Edelstein, wenn Ihr Euch durch das Spinnengift benommen fühlen solltet.", sourceObjective = "Benutzt den Smaragd von Aessina, um Pyrachnis zu beschwören und zu töten.", completion = "Oh, NEIN, Ihr seid ja über und über mit SPINNEN-BUÄRKS bedeckt!\n\n<Mylune bedeckt ihre Augen, um Euch nicht anblicken zu müssen.>\n\nIhr seid so tapfer, {race}. Ich hoffe, Ihr geht schon bald in die Feuerlande und tretet auf ALLE Spinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29163] = { id = 29163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm gegen die Flammen", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", sourceObjective = "Tötet 9 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", completion = "Ihr habt Euch gut geschlagen, {name}. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29164] = { id = 29164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut heulen will geübt sein", description = "Dem uralten Wolf, Lo'Gosh - oder, wenn Ihr es vorzieht, Goldrinn - stehen viele Waffen zur Verfügung, doch die am meisten unterschätzte ist wohl sein Geheul. Heute werden wir diese Waffe einsetzen, um Lylagar zu beschwören und zu töten, einen der Leutnants der Flamme, der in den Feuerlanden lauert.\n\nBezwingt jedwede Kreatur des Geheilten Hyjal und benutzt dann den Fangzahn des Wolfs während Ihr über ihren Leichnamen steht. Schon bald wird Euer Geheul über ganz Kalimdor erklingen.", sourceObjective = "Benutzt den Fangzahn des Wolfs über den Leichnamen von 10 Eindringlingen der Feuerlande innerhalb des Geheilten Hyjal.", completion = "<Matooklas vertraute Stimme dringt in Euer Bewusstsein.>\n\nJa, Ihr seid bereit. Nun werden wir den Schlag gegen Lylagar führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29165] = { id = 29165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Rudels", description = "<Matookla fährt fort:>\n\nDas östlichste Flammenportal ist das Reich von Lylagar. Stellt Euch vor das Portal und stoßt ein herausforderndes Geheul aus. Zwingt dann die Bestie dazu, sich zu ergeben.", sourceObjective = "Benutzt den Fangzahn des Wolfs, um Lylagar zu beschwören und besiegt ihn.", completion = "Ich habe die Echos Eurer triumphierenden Schreie über die Bergfelsen hinweg gehört.\n\nIch habe auch gehört wie Lylagar eine... andere Art von Schrei von sich gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29166] = { id = 29166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die andere Seite", description = "Eine der größten Gefahren, denen sich unsere Druiden innerhalb der Feuerlande stellen müssen, ist profanes Austrocknen. Unsere Proviantmeister verbringen sehr viel Zeit damit, die Feldflaschen für die Truppen auf der anderen Seite herzurichten. Wir haben allerdings andere Methoden.\n\nIm grüneren Dickicht im Osten solltet Ihr noch immer einige Blauknollenwinden finden, die noch nicht verbrannt wurden. Diese Pflanzen haben einen enormen Wasseranteil in ihren Wurzeln - und bieten dem müden Soldaten einiges an Energie.", sourceObjective = "Sammelt 7 Blauknollenwinden.", progress = "Dann wollen wir mal sehen... wie viele habt Ihr denn bisher sammeln können?", completion = "Ich werde diese hier sofort verpacken und verschicken lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29167] = { id = 29167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bansheekönigin", description = "Fürstin Sylvanas, die Anführerin der Verlassenen, soll eine der besten Kämpferinnen der Horde sein, vielleicht sogar so gut wie der Kriegshäuptling selbst!\n\nIch wollte sie schon immer mal treffen, {name}. Vielleicht kann ja <ein Abenteurer/eine Abenteuerin> wie Ihr eine Audienz mit ihr bekommen! Würdet Ihr mich zum Königsviertel von Unterstadt bringen, damit ich Fürstin Sylvanas treffen kann? Das ist ganz schön weit weg und die Wachen würden mich nie allein reinlassen!", sourceObjective = "Bringt Euer Waisenkind ins Königsviertel von Unterstadt und besucht Fürstin Sylvanas Windläufer. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", completion = "Sie ist genauso grimmig, wie ich sie mir vorgestellt hatte! Aber dieser Botschafter ist ganz schön wütend geworden, als ich mit Fürstin Sylvanas gesprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29169] = { id = 29169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiere im Inneren", description = "<Maywiki ist unruhig.>\n\nNach dem Fall Hakkars ist die Stadt der Gurubashi immer mehr verfallen und der Dschungel hat Zul'Gurub Stück für Stück zurückerobert. In den Schlupfwinkeln der alten Stadt leben jetzt einige mächtige Tiere.\n\nWir haben gesehen, welche Mächte die Gurubashipriester befehligen - mit ihren giftigen Gebräuen bringen sie sogar die Flora gegen uns auf. Bitte Ihr Helden, beseitigt diese Tiere bevor Jin'do und seine Handlanger sie zu ihren willenlosen Dienern machen!", sourceObjective = "Tötet die Blütenflügelschwarmkönigin, Tor-Tun den Schläfer sowie einen von Gahz'rankas verlorenem Nachwuchs in Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29170] = { id = 29170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind wir hier?", description = "<Finkles Helm versetzt Euch einen kleinen Schlag.>\n\nWas ist das für ein Ort? Es sieht so aus, als ob sie mit diesem Nethergroßdrachen etwas Schreckliches anstellen. Die Energie wird von dem Geschöpf auf die Frau übertragen! Wir müssen dieses Ritual unterbrechen!\n\nTötet Corla, um die Halle durchqueren zu können!", sourceObjective = "Tötet Corla, Botin des Zwielichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29171] = { id = 29171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind wir hier?", description = "<Finkles Helm versetzt Euch einen kleinen Schlag.>\n\nWas ist das für ein Ort? Es sieht so aus, als ob sie mit diesem Nethergroßdrachen etwas Schreckliches anstellen. Die Energie wird von dem Geschöpf auf die Frau übertragen! Wir müssen dieses Ritual unterbrechen!\n\nTötet Corla, um die Halle durchqueren zu können!", sourceObjective = "Tötet Corla, Botin des Zwielichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29172] = { id = 29172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiere im Inneren", description = "<Blutschlächterin T'ara beäugt Euch einen Moment lang.>\n\nNach dem Fall Hakkars is' die Stadt der Gurubashi immer mehr verfall'n und der Dschungel hat Zul'Gurub Stück für Stück zurückerobert. In den Schlupfwinkeln der alten Stadt leb'n jetzt einige mächtige Tiere.\n\nWir hab'n geseh'n, welche Mächte die Gurubashipriester befehlig'n - mit ihren giftigen Gebräuen bring'n sie sogar die Flora gegen uns auf. Du hältst dich für stark? Dann beseitige diese Tiere, bevor Jin'do und seine Handlanger sie zu ihren willenlosen Dienern mach'n!", sourceObjective = "Tötet die Blütenflügelschwarmkönigin, Tor-Tun den Schläfer sowie einen von Gahz'rankas verlorenem Nachwuchs in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "<T'aras Hauer bewegen sich ein wenig. Ist das ein Lächeln?>\n\nGut gemacht.\n\nWir werd'n heute Nacht ruhig schlaf'n in dem Wissen, dass Jin'do und Zanzil diese mächtigen Tiere nich' dem Willen der Gurubashi unterwerf'n können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29173] = { id = 29173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekundärziele", description = "Die Gurubashitrolle hab'n ihre mächtigsten Verbündeten zusammengeruf'n, um Zul'Gurub wiederaufzubau'n und das Schlingendorntal zurückzuerobern.\n\nDie mächtigsten unter diesen Verbündeten sind zwei monströse Trolle: Kaulema der Beweger und Mor'Lek der Zerleger, sowie ein gefährlicher Seelendieb namens Mortaxx.\n\nSie sind zwar nich' die Befehlshaber in Zul'Gurub, aber diese mächtigen Diener zu besieg'n wird dafür sorg'n, dass die Gurubashi so schnell nich' an die Macht komm'n.", sourceObjective = "Tötet Kaulema den Beweger, Mor'Lek den Zerleger und Mortaxx, das Schlagen der Stunde in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "Jin'dos Reich bricht um ihn herum in sich zusammen, wie die Ruinen dieser verlassenen Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29174] = { id = 29174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht ihren Willen", description = "Eine Stadt wie Zul'Gurub ähnelt den mächtigen Bäumen, die Ihr hier in der Umgebung sehen könnt.\n\nDer Stamm mag dick und das Laubdach dicht und üppig sein, aber ohne Nährstoffe aus den Wurzeln muss der Baum welken und umstürzen.\n\nJin'dos Armee wird hauptsächlich durch die Handlungen von zwei niederen Gurubashitrollen versorgt. Wenn Ihr diese Wurzeln durchtrennt, wird die Stadt umso schneller fallen.", sourceObjective = "Tötet Gub und den Meisterkoch der Gurubashi in Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29175] = { id = 29175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht ihren Willen", description = "Eine Stadt wie Zul'Gurub ähnelt den mächtigen Bäumen, die du hier in der Umgebung seh'n kannst.\n\nDer Stamm mag dick und das Laubdach dicht und üppig sein, aber ohne Nährstoffe aus den Wurzeln muss der Baum welk'n und umstürz'n.\n\nJin'dos Armee wird hauptsächlich durch die Handlungen von einer Handvoll niederer Gurubashitrolle versorgt. Wenn du diese Wurzeln durchtrennst, wird die Stadt umso schneller fall'n.", sourceObjective = "Tötet Gub und den Meisterkoch der Gurubashi in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "Das große Reich der Gurubashi fängt bereits an, zu vergeh'n.\n\nJetzt is' es nur noch eine Frage der Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29176] = { id = 29176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Häuptling", description = "Matrone Schlachterbe sagt, dass die Horde eine 'Stimme der Weisheit' mit Cairne Bluthufs Tod verloren hat. Ich weiß nicht, was das heißt, aber ich wollte ihn schon immer mal treffen. Einige der anderen Waisenkinder haben sogar seinen Hufabdruck.\n\nNehmt Ihr mich nach Mulgore mit? Unser Lehrer sagt, die Tauren bringen ihre Toten zu einem Ort, den sie die Teufelsfelsen nennen, und dort verehren sie sie. Lasst uns dorthin gehen und sehen, ob wir Cairne finden.", sourceObjective = "Besucht die Teufelsfelsen mit Eurem Waisenkind, um Cairne Bluthufs Scheiterhaufen zu sehen. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", progress = "Ich möchte öfter Mulgore besuchen.", completion = "Eines Tages werde ich auch so toll kämpfen können wie Cairne oder der Kriegshäuptling. Alle werden sich an meine Taten erinnern und die Geister werden auch meine Seele in ihre Reihen aufnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29177] = { id = 29177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelte Wachsamkeit", description = "Die Agenten des Zwielichts setzen ihren Angriff innerhalb dieses Kessels in den Feuerlanden fort. Wir dürfen nicht in unserer Offensive nachlassen! Schwingt Euch in die Lüfte und vernichtet so viele der Tjoster, wie Ihr könnt!\n\nVergesst nicht, Euch zunächst mit einer Lanze auszurüsten.", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt auf Avianas Wächter. Vernichtet 10 Zwielichttjoster, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", progress = "Unsere Wachsamkeit darf nicht nachlassen. Ganz besonders jetzt nicht, da sie auf die Probe gestellt wird!", completion = "Gut gemacht, {class}. Ich hoffe, Ihr vergesst uns hier in der Brutstätte nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29179] = { id = 29179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Elemente", description = "Die Elementare drängen weiterhin voran und ich erwarte nicht, dass sie bald nachlassen werden.\n\nIhr werdet sie im Norden finden, wo sie sich auf die Aschenfelder ergießen. Dünnt ihre Reihen aus.", sourceObjective = "Tötet 8 verkohlte Soldaten oder Bezwinger.", completion = "Wir wissen Eure fortgesetzten Anstrengungen zu schätzen, {class}. Wir werden diesen Krieg gewinnen, solange wir Kämpfer wie Euch an unserer Seite haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29180] = { id = 29180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versprechen, Versprechen...", description = "Meine Theorien bestätigen die Gerüchte, dass in Zul'Aman sagenhafte Schätze zu finden sind. Das bedeutet Reittiere und Anwesen für alle!\n\nNun ja, eins nach dem anderen. Ihr müsst Euch Euren Anteil natürlich verdienen...\n\nUnsere anfänglichen Bemühungen haben uns hier doch nicht so weit gebracht, wie ich es mir erhofft hatte. Tatsächlich sieht es so aus, dass meine Karte, und die Tagelöhner, denen ich sie geliehen habe, verschwunden sind. Sie sind aufgebrochen, um einen Troll namens Nalorakk zu jagen. Ich kann zwar die Gruppe ersetzen, aber ich brauche diese Karte!\n\nSolltet Ihr diese Aufgabe bewältigen, dann wird man von Euch sagen, dass Ihr derjenige wart, der Budd Winterhäldler geholfen hat, die Geheimnisse von Zul'Aman zu lüften!", sourceObjective = "Sucht auf Hohepriester Nalorakks Terrasse in Zul'Aman nach Budds Karte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29181] = { id = 29181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druiden der Kralle", description = "Himmelsfürst Omnuron und seine Druiden der Kralle waren eine furchterregende Streitkraft, damals in Hyjal. Ich weiß, dass sie die bekannten Himmel dieses Schlachtfelds vorziehen, aber die Zeit mag kommen, dass wir sie trotzdem hier brauchen.\n\nSolltet Ihr es schaffen, genügend Abzeichen zusammenzubekommen, so appelliert an Omnuron, dass seine Druiden an der Hauptfront sein sollten. Omnuron passt auf die seinen auf, aber er versteht auch die Wichtigkeit dieser Anstrengung.", sourceObjective = "Sammelt 150 Abzeichen des Weltenbaums.", progress = "Es ist gut, Euch wiederzusehen.", completion = "Ich verstehe. Ich kann nicht behaupten, dass ich erpicht darauf wäre, meine Leute in die Feuerlande zu schicken, aber mir war klar, dass es irgendwann notwendig werden würde.\n\nWir werden da sein, {class}. Danke, dass Ihr die Nachricht überbracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29182] = { id = 29182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flug der Sturmkrähen", description = "Viele der Druiden der Kralle haben sich auf Euer Geheiß zur Geschmolzenen Front begeben. Ihr solltet zu Himmelsfürst Omnuron bei Malfurions Bresche gehen und sehen, wie sich ihre Schwingen in diesen brennenden Himmeln schlagen.", sourceObjective = "Sprecht mit Himmelsfürst Omnuron bei Malfurions Bresche.", completion = "Diese Himmel sind tatsächlich beklemmend, aber wir haben es geschafft, uns größtenteils durchzunavigieren.\n\nEs kann sein, dass wir Eure Hilfe brauchen, um zusätzliche Landeplätze hinter dem Schmelzofen zu sichern. Ich werde Euch rufen, wenn wir so weit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29183] = { id = 29183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Tier 2 Heroic (Nth)" }
quests[29185] = { id = 29185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Tier 2 Heroic (1st)" }
quests[29186] = { id = 29186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fetisch des Hexlords", description = "Dieser neue Kriegsherr der Amani is' ohne den Schutz eines starken Hexendoktors nichts als ein zu groß geratener Haudrauf. Leider genießt er genau diesen Schutz.\n\nMit dem neuen Kriegsherrn im Bunde steht Hexlord Malacrass, der seit Jahrzehnten gefürchtetste Hexendoktor unter den Amani. Daakara wird sein Volk nich' dazu bring'n, sich der Kontrolle der Zandalari zu unterstell'n, es sei denn, der Hexlord befiehlt es.\n\nBesieg Hexlord Malacrass, bring mir seinen Lieblingsfetisch und ich garantier' dir eine angemessene Belohnung.", sourceObjective = "Erbeutet den Fetisch des Hexlords von Hexlord Malacrass in Zul'Aman.", progress = "Hast du Hexlord Malacrass ausgeschaltet?", completion = "Das ist also der Fetisch vom mächtigen Malacrass? Der macht sich sicher gut in meiner Sammlung, {name}. Und für dich is', glaub' ich, 'ne Belohnung angebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29189] = { id = 29189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nervige Netze", description = "Einige unserer Späher haben sich nicht zum Dienst zurückgemeldet. Wir fürchten, dass sie den tödlichen Spinnen in der Umgebung zum Opfer gefallen sind.\n\nAllerdings sind wir noch nicht bereit, alle Hoffnung fahren zu lassen, denn die Spinnen wickeln ihre Opfer oft noch lebend ein, um sie später zu... konsumieren.\n\nGeht und sucht bei den Säulen im Norden nach eingesponnenen Opfern. Vielleicht gelingt es Euch, einige unserer Brüder zu retten.", sourceObjective = "Befreit 8 Opfer aus Aschenweberkokons.", completion = "Unsere verlorenen Verbündeten sind bereits zurückgekehrt. Sie sind gebeutelt, aber sie sind am Leben. Vielen Dank, dass Ihr sie gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29190] = { id = 29190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensteigen", description = "Neulich, als ein paar von uns mit der Matrone unterwegs waren, haben wir einen Goblin gesehen, der einen Wagen mit Spielzeugen geschoben hat. Er hatte Puppen, Rennwagen aus Kupfer, Lederbälle und Papierdrachen. Ich wollte schon immer einen Drachen haben und die Matrone sagt, dass ich nur all mein Geld sparen muss, dann kann ich mir einen kaufen, aber das dauert noch ewig.\n\nIch glaube, der Name des Goblins war Blax Flaschenzünder oder so was. Wenn wir ihn aufspüren, könnten wir uns ein paar Drachen holen und sie steigen lassen? Ich habe ihn und seinen Karren in der Gasse gesehen.", sourceObjective = "Kauft einen Doppelpack Papierdrachen von Blax Flaschenzünder in Orgrimmars Gasse und benutzt sie, um mit Eurem Orcwaisenkind einen Drachen steigen zu lassen. Wenn Euer Waisenkind nicht bei Euch ist, solltet Ihr es herbeirufen.", progress = "Ich dachte, dass ich ganz bestimmt eine Million Jahre lang sparen muss, bis ich mir einen Drachen kaufen kann!", completion = "Danke für den Drachen, {name}. Jedesmal wenn ich ihn steigen lasse, werde ich an den Tag denken, an dem Ihr ihn mir geschenkt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29191] = { id = 29191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker Eis", description = "Es gibt einen brandneuen Eisladen in Orgrimmar und dort verkaufen sie nicht einfach nur gewöhnliches Eis. Deren Eis wird von einem verrückten Goblinmagier gemacht! Glaubt Ihr, es verschwindet, wenn ich es nicht innerhalb von fünfzehn Minuten schaffe?\n\nIch wette, das schmeckt richtig lecker. Gehen wir kosten?\n\nIch habe einige der anderen Kinder darüber reden hören und die sagen, der Laden heißt 'Der Kältekegel' und steht im Südteil der Goblinslums.", sourceObjective = "Kauft ein Eis im Laden 'Kältekegel' und teilt es mit Eurem Waisenkind.", progress = "Eiscreme mag ich am liebsten.", completion = "Ich glaube, das ist das erste Mal, dass ich einen Goblin Essen machen sehe, für das er keine große, laute Maschine benutzt, die dicken Rauch spuckt. Vielleicht würden mehr Leute ihre Gerichte mögen, wenn sie sie wie normale Leute zubereiten würden... oder wie Magier! Das Eis war so lecker!", sourceObjectiveStatus = "unverified-source-field" }
quests[29192] = { id = 29192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter sehen zu", description = "Wir müssen vorsichtig vorgehen, {class}. Fandrals Druiden der Flamme praktizieren ihre feurige Magie jenseits der Säulen im Norden.\n\nIch möchte, dass Ihr einen dieser Druiden lebend gefangennehmt, damit wir ihn befragen können. Wir müssen jede Gelegenheit beim Schopf ergreifen, um ihre Pläne in Erfahrung zu bringen.\n\nEine meiner Wächterinnen wird Euch begleiten. Folgt ihren Anweisungen, wenn Ihr am Leben bleiben wollt.", sourceObjective = "Greift einen Druiden der Flamme an, um ihn zu schwächen und lockt ihn dann in die Falle der Schattenwächterin.", progress = "Die Druiden der Flamme sind fern jeder Erlösung. Jetzt werden sie für ihre Verbrechen zur Rechenschaft gezogen.", completion = "Ich bin beeindruckt, {class}. Eure Taten werden unter den Schattenwächtern nie vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29193] = { id = 29193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf gut Glück", description = "Wir haben guten Nutzen aus unserer Zeit gezogen, <Sterblicher/Sterbliche>.\n\nWährend Ihr auf der Ebene des Feuers gekämpft habt, haben meine Wächter und ich herausgefunden, wann und vor allem wo unser Blick behindert wurde.\n\nWir haben festgestellt, dass der Schleier über den Nexus, im hohen Norden, im Reich des blauen Drachenschwarms, gelegt wurde.\n\nIch habe das zeitlose Auge darauf abgestimmt, dass es Euch zeigen wird, was uns hier bisher verhüllt bleibt.\n\nBringt es sofort nach Kaltarra und findet einen geeigneten Ort, um das Auge zu aktivieren.\n\nGeht jetzt. Wir haben keine Zeit zu verlieren...", sourceObjective = "Bringt das zeitlose Auge nach Kaltarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[29194] = { id = 29194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie in einem Spiegel", description = "<Tarecgosa hört Euch zu, während Ihr Eure Anwesenheit in Kaltarra erklärt.>\n\nEure Geschichte klingt glaubwürdig, {class}. Viel hat sich seit Malygos' Tod geändert - wenig davon zum Guten.\n\nIch weiß von dem Gerät, das Ihr mit Euch führt, und ich erkenne Anachronos' Magie in seiner Erschaffung. Es gibt in ganz Kaltarra nur einen Ort, der es erlaubt, dass dieses zeitlose Auge diskret eingesetzt wird.\n\nIhr werdet meine Hilfe brauchen, falls Ihr auf Erfolg hofft. Sprecht mich im Inneren des Nexus erneut an und sie soll Euch gewährt werden.", sourceObjective = "Blickt in das zeitlose Auge am Nethervortex im Inneren des Nexus.\n\nTrefft Tarecgosa im Nexus, wo sie Euch zum Riss eskortieren wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29195] = { id = 29195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ritual der Flamme", description = "Es scheint, als hätten wir alles unter Kontrolle. Unser Invasionsportal zu den Feuerlanden wird jeden Augenblick geöffnet werden und die Elementare haben sich bisher nicht besonders zur Wehr gesetzt.\n\nHelft unseren Druiden, indem Ihr die letzten paar Elementare erledigt. Sobald das Tor dann geöffnet ist, können wir losschlagen.", sourceObjective = "Bekämpft die Wellen der verkohlten Eindringlinge auf dem Nordunegrat bis das Portal geöffnet ist.", progress = "Setzt den Kampf fort, {name}. Es sollte jetzt nur noch ein wenig dauern.", completion = "Leyara... sie ist am Leben. Ich spüre, dass Fandral die Hände mit im Spiel hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[29196] = { id = 29196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Heiligtum!", description = "Für den Augenblick sollten wir uns keine Sorgen um diese \"Druidin der Flamme\" machen. Wir müssen uns um die Fortführung unserer Operation kümmern.\n\nKehrt zu Matookla beim Heiligtum von Malorne zurück. Wenn Ragnaros auf unsere Ankunft vorbereitet war, dann erwarte ich, dass seine Streitkräfte schon bald einen Gegenangriff starten werden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne auf dem Hyjal.", completion = "Was ist dort oben geschehen? Ich habe Feuer gesehen und... Ach, unwichtig, Ihr könnt es mir später erzählen. Wir haben andere, dringendere Dinge, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29197] = { id = 29197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalt erwischt", description = "Es sieht so aus, als sei unser Invasionsplan nach hinten losgegangen. Einige unserer Vögel haben sich bereits zurückgemeldet und berichten von Feuern, die in den Tälern des zentralen Hyjal ausgebrochen seien.\n\nNun sind viele von unseren Druiden im Feld gestrandet, unvorbereitet für solch einen großangelegten Angriff. Thisalee war in der Nähe des Aschensees und verschiedene andere befanden sich beim Geheilten Hyjal, im Nordosten.\n\nGeht, {name}! Findet sie und stellt sicher, dass sie dieser Explosion nicht zum Opfer fallen!", sourceObjective = "Helft Ahnenzweig, Thisalee Krähe, Tholo Weißhuf und Anren Schattensucher, den Flammen zu entkommen.", completion = "{name}! Ihr seid zurück!\n\nSie haben uns zum Heiligtum zurückgedrängt. Wir sind ihnen zahlenmäßig weit unterlegen. Bei diesem Tempo haben die Wächter des Hyjal kaum eine Chance zu überleben.\n\nIch bin froh, dass Ihr hier an unserer Seite steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29198] = { id = 29198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heiligtum darf nicht fallen", description = "Malfurion arbeitet an einem Wunder für uns. Er glaubt, dass er in diesen gefährlichen Zeiten Malorne wiederauferstehen lassen kann, um das Heiligtum zu beschützen. Ich habe Vertrauen in ihn.\n\nIn der Zwischenzeit müssen wir die Stellung hier halten. Haltet Euch bereit und stellt sicher, dass dem Erzdruiden kein Leid widerfährt.", sourceObjective = "Schützt Malfurion, während er Malorne wiederauferstehen lässt.", completion = "Malornes Stärke alleine hat vielleicht gerade Kalimdor gerettet. Sich vorzustellen, dass Malorne heute zurückgekehrt ist, nach so langer Abwesenheit...\n\n<Malfurion überblickt die Gegend.>\n\nWir haben heftige Verluste erlitten. Obwohl die unmittelbare Bedrohung nicht länger besteht, werden unsere Streitkräfte doch Zeit brauchen, zu gesunden, und alle verbleibenden Feuer am Hyjal zu löschen.\n\nUnser Angriff auf die Feuerlande wird warten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29199] = { id = 29199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung rufen", description = "Durch die Gegenwehr während unseres Invasionsversuchs haben wir schwere Verluste erlitten. Unser zweiter Versuch darf einfach nicht fehlschlagen.\n\nWir brauchen Verstärkung, bevor wir uns an einer neuen Invasion versuchen können. Bitte, {name}, arbeitet mit Matookla zusammen, um neue Quellen zu erschließen, um Verstärkung zu ermöglichen. Dann werden wir uns zum zweiten und letzten Mal daran versuchen, die Feuerlande anzugreifen.", sourceObjective = "Sammelt 20 Abzeichen des Weltenbaums.", progress = "Je eher wir einen Durchbruch durch unser Invasionsportal erzielen können, umso besser.", completion = "Ausgezeichnete Arbeit. Ich fordere sofort unsere Verstärkung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29200] = { id = 29200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyara", description = "Bevor wir aufbrechen, {name}, gibt es noch eine weitere Sache, um die Ihr Euch kümmern solltet.\n\nEine dieser \"Druiden der Flamme\" wurde in den Ruinen im Nordwesten gesehen. Ich schätze, dass es dieselbe ist, die uns vor einigen Tagen am Portal angegriffen hat. Jetzt wäre ein idealer Zeitpunkt, um herauszufinden, was sie wirklich will... und sie, wenn nötig, zu erledigen.\n\nKümmert Euch um diese Flammendruidin, dann können wir auf dem geplanten Weg fortfahren.", sourceObjective = "Findet Leyara, die Druidin der Flamme.", completion = "<Matookla hört aufmerksam zu, als Ihr erklärt, was geschehen ist.>\n\n<Sie ist sichtbar erschüttert.>\n\nIhr seid von unserem Plan abgewichen, {name}. Unser Angriff hätte heute stattfinden sollen! All diese Vorbereitungen... wie können wir ohne die Hilfe Hamuuls siegreich sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[29201] = { id = 29201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Tore der Hölle", description = "Wir werden später um Hamuul trauern. Er war das erste von vielen unvermeidlichen Opfern dieses Kriegs... Aber unser Angriff kann nicht warten und die Triebkraft, die wir über die letzten Tage aufgebaut haben, darf nicht verschwendet werden.\n\nHeute greifen wir die Feuerlande an.\n\nDas Portal auf dem Nordunegrat ist jetzt geöffnet. Unsere Verstärkungen sind vorbereitet und sie warten nur auf meinen Befehl, um durch das Portal zu gehen.\n\nWir werden uns auf der anderen Seite des Portals wiedersehen. Sobald wir einmal dort sind, werden wir sicherstellen, dass unsere Stellung gesichert ist.", sourceObjective = "Geht durch das Portal auf dem Nordunegrat und helft Malfurion dabei, die Stellung an der Geschmolzenen Front zu sichern.", completion = "Sehr gut gemacht, {class}. Wir haben es geschafft, uns im Reich des Feindes eine Stellung einzurichten, ohne dass sie es bemerkt haben. In genau diesem Moment bewegen sich unsere Armeen voran und errichten eine Front.\n\nUns steht ein langer, brutaler Krieg bevor. Es ist meine Hoffnung, dass Ihr an unserer Seite sein werdet, um uns hierbei zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29202] = { id = 29202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Runentotem", description = "Ich entschuldige mich dafür, dass ich Euch gegenüber zuvor so kurzangebunden war. Der Verlust von Hamuul hat mich schockiert und es ist nicht einfach, damit umzugehen.\n\nSie haben seinen Körper hereingebracht, während Ihr weg wart. Er lebt, aber er hat - wie Ihr Euch denken könnt - sehr, sehr schwere Verbrennungen erlitten.\n\nDie Wunden sind tief. Vielleicht wird er es nicht überleben.\n\nIch habe ihm einige unserer besten Heiler zur Seite gestellt, die sich um ihn kümmern. Wenn es nicht zu viel verlangt ist, könntet Ihr vielleicht mit Dorda'en Nachtweber sprechen? Er und die anderen Pfleger könnten vielleicht Eure Hilfe brauchen.", sourceObjective = "Sprecht mit Dorda'en Nachtweber beim Heiligtum von Malorne auf dem Hyjal.", completion = "Ja, Hamuul lebt. Ihr könnt ihn in dem Zelt hinter mir besuchen, aber seid bitte vorsichtig. Er ist in sehr schlechtem Zustand und wir tun alles in unserer Macht Stehende, um ihn am Leben zu halten und es ihm bequem zu machen.\n\nWer auch immer das dem Erzdruiden angetan hat, hat keinerlei Gnade gezeigt. Ich hoffe, dass Ihr Euch dafür irgendwann revanchieren könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29204] = { id = 29204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff der Wächterinnen", description = "Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nIch habe ihr eine große Gruppe unserer Männer unterstellt, aber ihre Erfolgsgruppen würden enorm steigen, wenn Ihr Euch ihr anschließen würdet. Es ist Eure Entscheidung, {name}.", sourceObjective = "Wenn Ihr den Wächterinnen helfen wollt, den Einsamen Turm anzugreifen, dann sprecht mit Hauptmann Saynna Sturm in den nordöstlichen Aschenfeldern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29205] = { id = 29205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsame Turm", description = "Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nGeht dorthin und eskortiert einen ihrer Druiden zum Turm mit allen Streitkräften, die sie entbehren kann. Euch steht ein ordentlicher Kampf bevor - stellt sicher, dass der Druide bis zum Ende überlebt oder es wird ihnen nicht möglich sein, den Turm zu erobern.", sourceObjective = "Beschützt einen der Druiden, die versuchen, den Einsamen Turm einzunehmen.", completion = "Gut gemacht, {class}. Das sollte ein guter Ausgangspunkt sein, um weiter in feindliches Gebiet vorzudringen.\n\nIch kann in der Nähe Druiden der Flamme spüren. Vielleicht sollten wir auch mit ihnen kurzen Prozess machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29206] = { id = 29206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Feuer", description = "Der Himmelsfürst Omnuron und seine Druiden versuchen durch den Schmelzofen im Nordwesten durchzubrechen. Es war ihnen möglich, über die Gefahren hinwegzufliegen, aber sie benötigen wirklich jemand auf dem Boden, der ihnen hilft, das Gebiet jenseits des Feuers zu sichern... jemanden wie Euch.\n\nWenn Ihr den Druiden der Kralle helfen wollt, so wartet darauf, dass einer von Omnurons Windrufern versucht, das Feuer zu durchbrechen, bleibt in seiner Nähe und beschützt ihn vor Angreifern aus den Flammen.", sourceObjective = "Eskortiert einen Windrufer durch den Schmelzofen und sichert den Eingang zum Geschmolzenen Strom.", completion = "Es ist gut zu sehen, dass der Himmelsfürst endlich jemand Fähigen ohne Flügel gefunden hat. Die Fähigkeit zu fliegen nützt uns in diesen beengten Umständen und im Anbetracht der Thermalwinde jenseits dieses Grats wenig.\n\nEs sieht so aus, als müssten wir uns auf konventionellere Taktiken verlassen. Seid Ihr dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[29208] = { id = 29208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Freund", sourceObjective = "Zwischen all den Raptoren in Mandokirs Reich sticht ein vertrautes Gesicht heraus. Sie ist etwas größer geworden und hat ein paar mehr Narben, aber sie ist noch immer hier und wartet auf Eure Rückkehr.\n\nSie erkennt Euch wieder. Ihr Papa ist endlich da, um sie zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29210] = { id = 29210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdulden der Hitze", description = "Shalis ist mit einem unserer Druiden losgezogen, um einen Druiden der Flamme davon abzuhalten, in den Feurigen Tiefen unter uns ein Beschwörungsritual zu vollziehen. Ihnen ist aufgetragen worden, den Druiden zu töten, aber ich brauche Euch, um das Ritual zu stoppen.\n\nIhr werdet den Eingang zu den Feurigen Tiefen östlich der Magmaquellen finden. Sobald Ihr im Inneren seid, werdet Ihr 8 blaue Runen über die Höhle verteilt sehen. Ihr könnt diese Runen benutzen, um Euch vor den feurigen Kreaturen zu schützen, aber Ihr werdet alle von ihnen austreten müssen, um das Ritual zu beenden. Ihr werdet schnell handeln müssen.", sourceObjective = "Findet den Weg in die Feurigen Tiefen und zerstört dann alle 8 der blauen Runen, die sich im Inneren befinden.", progress = "Ihr müsst die Runen zerstören! Beeilt Euch!", completion = "Gut gemacht!\n\nSie haben versucht, Rituale wie dieses überall an der Geschmolzenen Front durchzuführen, doch bisher konnten wir dieses Vorhaben noch immer vereiteln. Hoffentlich werdet Ihr auch in Zukunft da sein, um uns dabei zu helfen, diesen Trend fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29211] = { id = 29211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solarkernzerstörung", description = "Der Kampf hat uns direkt zu Fandrals Haustür gebracht. Seine Druiden kanalisieren Energien der Feuerlande in ein Behältnis, das der Solarkern genannt wird.\n\nSollte dieses Behältnis auf Azeroth explodieren, wird keinem von uns eine Heimat bleiben, in die wir zurückkehren könnten.\n\nWir müssen jetzt einen Schlag gegen den Solarkern führen, solange er noch angreifbar ist. Ihr könnt das infernalische Gerät auf der nordöstlichen Kante der Insel finden.", sourceObjective = "Sprengt den Solarkern.", completion = "Ist er zerstört? Gut. Ich bezweifle, dass das Fandral lange aufhalten wird, aber wir müssen uns jeden Vorteil sichern, den wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29213] = { id = 29213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie geht's dem Jäger?", description = "Das sah nich' gut aus. Der Panther stand unter irgendeiner Art von mächtiger Magie... Wir sollt'n besser nach dem Jäger seh'n und schau'n, wie's ihm geht.", sourceObjective = "Seht nach Grent Düsterhammer.", completion = "Oh... Mein Kreuz. Bist du das, Bruder?", sourceObjectiveStatus = "unverified-source-field" }
quests[29214] = { id = 29214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattenwächterinnen", description = "Die Schattenwächterinnen sind zurück im Geheilten Hyjal. Ich weiß, dass sie den Verlust von Fandral aus ihrem Gewahrsam sehr ernst nehmen, weshalb es wenig Ansporn bedürfen wird, sie in die Feuerlande zu bringen und die Druiden der Flamme zu jagen.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr Euch bei Hauptmann Saynna Sturmläufer beim Heiligtum von Malorne melden und Euch ihre Unterstützung sichern.", sourceObjective = "Sammelt 150 Abzeichen des Weltenbaums.", progress = "Ja, {class}?", completion = "Ich verstehe. Die Zeit ist also gekommen, dass wir uns der Jagd in den Feuerlanden anschließen. Meine Schwestern werden hinter Euch stehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29215] = { id = 29215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd beginnt", description = "Die Schattenwächterinnen haben sich auf Eure Bitte hin dem Kampf an der Geschmolzenen Front angeschlossen. Ihr solltet Hauptmann Saynna Sturmläufer finden und dafür sorgen, dass sie einen Weg finden, ihre Fähigkeiten am besten einzusetzen.", sourceObjective = "Sprecht mit Hauptmann Saynna Sturmläufer bei Malfurions Bresche.", completion = "Hallo {name}. Es ist gut, Euch wiederzusehen.\n\nIhr hättet Euch keine Sorgen machen müssen, wir haben uns hier ganz gut eingerichtet. Ich habe mehrere meiner Wächterinnen ausgeschickt, um dabei zu helfen, die Druiden der Flamme zur Strecke zu bringen und ich habe die Angriffspläne für den Einsamen Turm angefertigt. Wenn der Zeitpunkt gekommen ist, werdet Ihr Euch uns vielleicht dort anschließen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29216] = { id = 29216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "alfurion's Breach" }
quests[29217] = { id = 29217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangenen Späher", description = "Nachdem wir hier angekomm'n sind, habe ich meine Späher losgeschickt, um mehr über die Anwesenheit der Zandalari hier in Zul'Aman zu erfahr'n. Viele sind mit nützlichen Informationen zurückgekehrt, aber vier werd'n noch immer vermisst. Wenn wir nich' schnell handeln, werd'n die Handlanger des neuen Kriegsherrn sie zu Ehren der Gesandten der Zandalari opfern.\n\nFinde meine Späher, {name}, und befrei sie, bevor die Priester sie opfern!", sourceObjective = "Befreit die gefangenen Späher: Hazlek, Bakkalzu, Norkani und Kasha. Sie werden von den Hohepriestern der Amanitrolle gefangengehalten.", progress = "Hast du meine Späher gefund'n?", completion = "Ich hätte nich' gedacht, die nochmal wiederzuseh'n, {name}. Die Informationen, die sie gesammelt hab'n, werd'n der Schlüssel dazu sein, den Einfluss der Zandalari in Zul'Aman zu brech'n. Herzlichen Dank von mir und meinen Spähern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29218] = { id = 29218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen des Weltenbaums" }
quests[29219] = { id = 29219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwembas Geist", description = "Es sind gefährliche Zeiten für uns Dunkelspeere. Die Zandalaritrolle versammeln alle Trollklans und hab'n vor, die Länder wiederzuerobern, die sie verlor'n hab'n.\n\nWir versuch'n alle zu warnen, die wir können. Aber es könnte zu spät sein.\n\nEin weiterer Dunkelspeertroll is' ins Schlingendorntal gegang'n, um die Leute zu warnen. Aber es is' nich' sicher, allein da durchzuwandern.\n\nHilf mir, ihn zu find'n und sicherzustell'n, dass die Leute im Schlingendorntal von der Bedrohung durch die Trollstämme erfahr'n.\n\nIch werd' meinen Geist mit deinem verbind'n. Wenn du ins Schlingendorntal gelangst, werd' ich dir helf'n können.", sourceObjective = "Warnt die Bewohner des Schlingendorntals und findet den anderen Abgesandten der Dunkelspeere.", progress = "Das wird keine einfache Aufgabe, {name}.", completion = "Da siehst du's, {name}. Sieht aus, als würd'n wir einen Angriff auf die Gurubashi in Zul'Gurub anführ'n.\n\nDies sind dunkle Zeiten für uns Dunkelspeere. Aber für die Zandalaritrolle werd'n sie noch dunkler. Sie sind zu weit gegang'n.\n\nDu bist gut zu Bwemba gewes'n, hoffentlich wirst du weiter das ganze Schlingendorntal unterstütz'n.\n\nMög'n die Geister mit dir sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29220] = { id = 29220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Bambala", description = "Zuerst sollt'n wir dort nachsehen, wo vermutlich der erste Angriff stattfindet, also in Bambala.\n\nBambala is' gefährlich nahe an der Trollstadt Zul'Gurub dran... ein leichtes Ziel.\n\nVielleicht find'n wir den Abgesandten dort. Hoffentlich is' es noch nich' zu spät.", sourceObjective = "Reist nach Bambala im Nördlichen Schlingendorntal, um den Abgesandten der Dunkelspeere zu finden.", completion = "Wie's aussieht, sind die Geister mit dir, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29221] = { id = 29221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen und Gift", description = "Die Warnung hat geholf'n, {name}.\n\nWir hab'n mehr Kopfjäger für unsere Verteidigung versammelt. Aber Kopfjäger... na ja, die jag'n für gewöhnlich nich' die Köpfe von Schlangen. Wir werd'n also bald überwältigt sein. Diese Schlangen scheinen von überall herzukomm'n. Und wahrscheinlich wird's nur noch schlimmer.\n\nHilf uns, die Schlangen zu töt'n und lass Bwemba ihr Mojo verwend'n, damit die Vergifteten geheilt werd'n.", sourceObjective = "Tötet Dschungelschlangen und untersucht die vergifteten Kopfjäger, damit Bwemba sie heilen kann.", completion = "Danke für deine Hilfe, {class}. Die Schlangen sind ja überall.", sourceObjectiveStatus = "unverified-source-field" }
quests[29222] = { id = 29222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister sind mit uns", description = "Mit den Schlangen hat was nich' gestimmt, {name}. In ihrem Gift war eine Spur von schlechtem Mojo und das passiert nich' von Natur aus.\n\nDas Freudenfeuer in der Mitte des Lagers - dort können wir ein Ritual abhalt'n.\n\nWas auch immer diese Schlangen zum Angreif'n bringt, passt bestimmt noch gut auf sie auf.\n\nDas einzige Problem is', {name}, dass ich nur in Geisterform hier bin. Du musst meine Hände sein. Geh zu dem Feuer und bereite es für mich vor. Dann kümmere ich mich um den Rest.", sourceObjective = "Bereitet das Freudenfeuer vor dem Schlangenschrein in der Nähe von Bambala für Bwembas Ritual vor.", completion = "Venoxis... das kann nix Gutes heiß'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29223] = { id = 29223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwary wird es wissen", description = "Die Gurubashi sind also auf dem Vormarsch und die benutz'n Schlangen als erste Angriffswelle.\n\nWeißt du, wer sich darauf versteht, die Wildtierbestände hier klein zu halt'n? Die Jäger in Nesingwarys Expedition.\n\nSpazier doch mal da 'rüber und frag sie nach einer guten Methode, wie man Schlangen loswird.\n\nWenn die's nich' wiss'n, dann solltest du sie wenigstens warn'n, dass mit diesen Schlangen was nich' stimmt.", sourceObjective = "Warnt die Jäger in Nesingwarys Expedition im Nördlichen Schlingendorntal.", completion = "Über die Schlangen wissen wir Bescheid, {name}. Aber da draußen lauert noch etwas anderes... Der Dschungel ist zum Leben erwacht, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29225] = { id = 29225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen mit Konsequenzen", description = "<Tarecgosa hört gebannt zu, während Ihr Eure Vision schildert.\n\nUnmöglich!\n\nNicht einmal Arygos würde es wagen, so weit zu gehen.\n\nIch stelle hier nicht Eure Integrität in Frage, {class}, doch müsst Ihr verstehen, Euer sterblicher Geist kann leicht getäuscht werden.\n\nDoch in jedem Fall muss Kalecgos über diese Ereignisse unterrichtet werden. Ihr müsst sofort nach Nordrassil reisen und ihn aufsuchen.\n\nIch bleibe hier und beseitige die Beweise unserer Aktivitäten. Erzählt sonst niemandem davon.", sourceObjective = "Sprecht mit Kalecgos bei Nordrassil auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29226] = { id = 29226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Spurenleser auf der Spur", description = "Wir schlagen hier schon seit Tagen die Schlangen zurück, {name}. Aber Schlangen sind nichts im Vergleich zu dem, was sich da sonst noch so im Dschungel herumtreibt.\n\nWir Jäger werden zu Gejagten.\n\nEin großer Panther namens Mauti hat meine Männer einen nach dem anderen in den Busch weggezerrt.\n\nWir haben Grent Düsterhammer, einen unserer besten Jäger, auf dieses Mistviech angesetzt.\n\nDüsterhammer ist nach Osten aufgebrochen. Vielleicht könnt Ihr ihn dort finden.", sourceObjective = "Findet Düsterhammer im Nördlichen Schlingendorntal.", completion = "Schhh....", sourceObjectiveStatus = "unverified-source-field" }
quests[29227] = { id = 29227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Jägers", description = "Die Bestie, die uns auf der Spur war... ich habe nach ihr gejagt.\n\nIhr Name ist Mauti. Sie ist ziemlich schlau. Doch sie hat einen großen Fehler begangen, als sie meinen Bruder getötet hat. Das wird sie teuer zu stehen kommen. Der alte Düsterhammer ist ihr auf den Fersen.\n\nIch habe sie oberhalb von Kurzens Truppenlager herumstreifen sehen. Wenn wir schnell zuschlagen, können wir ihr den Garaus machen.\n\nSeid Ihr bereit, {name}?", sourceObjective = "Gewährt Grent Düsterhammer die Genugtuung, die er sich wünscht, indem Ihr Mauti tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29228] = { id = 29228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dieser Katze", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", sourceObjective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", progress = "Unterschätzt Mauti nich'. Er ist ein schlauer Panther.", completion = "Da sind wir... Der Jäger, er is' in der Höhle. Die Bestie... Etwas stimmt mit ihr nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29229] = { id = 29229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dieser Katze", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", sourceObjective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29230] = { id = 29230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mauti", description = "Ich hab das Gefühl, dass mit dem Panther was nich' stimmt, {name}. Fühlt sich unnatürlich an. Ich werd' ein paar Rituale über dem Leichnam abhalt'n müss'n. Töte Mauti und dann werd'n wir mal seh'n, was wir herausfinden können, {name}.", sourceObjective = "Bringt Bwemba zu den Überresten von Mauti.", completion = "Hohepriesterin Kilnara steckt hinter dieser Monstrosität. Das sieht nich' gut aus. Wir sollt'n nach dem Zwerg seh'n und dann herausfind'n, was sonst noch so los ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29231] = { id = 29231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie geht's dem Jäger?", description = "Das sah nich' gut aus. Der Panther stand unter irgendeiner Art von mächtiger Magie... Wir sollt'n besser nach dem Jäger seh'n und schau'n, wie's ihm geht.", sourceObjective = "Seht nach Grent Düsterhammer.", completion = "Oh... Mein Kreuz. Bist du das, Bruder?", sourceObjectiveStatus = "unverified-source-field" }
quests[29232] = { id = 29232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Botten", description = "Ah... Ihr seid es, {name}. Mauti... Sie ist tot? Dann wurde mein Bruder gerächt. Ich habe nur noch eine Bitte an Euch... Dieser Schuft hier hat an meinen nackten Füßen herumgekratzt. Kein Zwerg sollte ohne Stiefel unter die Erde müssen.\n\nBitte, begrabt mich mit meinen Stiefeln.", sourceObjective = "Holt die Stiefel von Grent Düsterhammer.", progress = "Habt Ihr meine Stiefel? Gewährt einem Zwerg doch seinen letzten Wunsch, ja?", completion = "Da-Danke… Kumpel.\n\nPapi...?\n\n\nBist...\n\n\n\ndu das...\n\n\n\n\n...", sourceObjectiveStatus = "unverified-source-field" }
quests[29233] = { id = 29233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Grom'gol", description = "Dieser Tod war nich' vergebens, {name}. Wir hab'n herausgefund'n, dass Kilnara auf Streifzug is'. Das sieht ziemlich düster für uns aus.\n\nWir seh'n besser nach, wie es in Grom'gol im Westen aussieht. Vielleicht find'n wir ja auch meine Kontaktperson dort.", sourceObjective = "Begebt Euch zum Basislager Grom'gol.", completion = "Erst waren es Schlangen, dann Panther und jetzt sind es blutrünstige Trolle.\n\nBloß gut, dass Ihr hier seid, {class}, es gibt reichlich Trolle abzuschlachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29235] = { id = 29235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt Grom'gol", description = "Ich hoffe, Ihr kämpft gern, {name}. Euer Trollfreund ist hier durchgekommen und hat uns gewarnt, dass die Gurubashi auf dem Vormarsch sind. Ich hätte nie gedacht, dass die Schlacht so glorreich werden würde.\n\nKommt, werft Euch mit uns in die Schlacht und zeigt diesen Gurubashitrollen die Macht der Horde!", sourceObjective = "Helft dabei, das Basislager Grom'gol drei Minuten lang zu verteidigen.", completion = "Diese Trolle strömen immer weiter auf uns ein, {name}. Fantastisch!\n\nWie ich schon sagte, war der Abgesandte der Dunkelspeere für kurze Zeit hier. Er hat uns gewarnt, dann ist er wieder aufgebrochen.\n\nThysta, unsere Windreitermeisterin, hat ihm geholfen, zu seinem nächsten Bestimmungsort zu kommen, vielleicht kann sie Euch helfen.\n\nGute Jagd, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29236] = { id = 29236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Hartzangs Versteck", description = "Bwemba... Seid Ihr das?\n\nEuer Kontakt war hier. Er war erpicht darauf, zum nächsten Ort zu eilen und die Leute zu warnen. Ich habe ihn auf einen Flug nach Hartzangs Versteck am Schlingendornkap geschickt. Ich hoffe, er war nicht zu spät.\n\nIhr könnt einen meiner Wyvern verwenden, um zum Versteck zu gelangen.\n\nSagt Bescheid, wenn Ihr bereit seid aufzubrechen, {name}.", sourceObjective = "Begebt Euch nach Hartzangs Versteck am Schlingendornkap.", completion = "Das sieht nich' sehr gut aus, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29237] = { id = 29237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoozombies", description = "Die Leute... alles Zombies, Voodoozombies! Das wird nich' schön, {name}.\n\nDu musst die alle töt'n.\n\nAber sobald sie erledigt sind, gibt es einen Weg, wie ich sie zurückhol'n kann. Wieder in die Personen verwandeln, die sie war'n.\n\nWir müss'n schnell handeln, die Zombies schlafen nich'.", sourceObjective = "Rettet 10 Überlebende des Verstecks.", completion = "Wir hab'n getan, was wir konnt'n, {name}. Wir können diese Zombies nich' länger bekämpf'n. Wir müss'n die Wurzel dieses Voodoos ausfindig mach'n. Und ich glaub', ich weiß, wo wir anfang'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[29238] = { id = 29238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorbene Vorräte", description = "Einige der Überlebenden hab'n Nahrungsmittel erwähnt, {name}. Wir sollt'n ihre Vorräte überprüf'n. Ich hab ein schlechtes Gefühl bei der Sache.", sourceObjective = "Überprüft den Ort in Hartzangs Versteck, an dem Nahrungsmittel zubereitet werden.", completion = "Zanzil... Es fängt alles an, Sinn zu ergeb'n. Wenn ich meinen Kontakt find'n kann, können wir einen Angriffsplan entwickeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29239] = { id = 29239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zweig von Nordrassil", description = "Viel hat sich seit unserem letzten Gespräch ereignet.\n\nIch habe es auf mich genommen, zum Nexus zu reisen und Anachronos' Artefakt zurückzuholen, doch nicht ohne es selbst zu verwenden. Jetzt kann auch ich das bezeugen, was Ihr gesehen habt.\n\nBevor wir noch weiter darüber reden, erlaubt mir, Euch meine Dankbarkeit auszusprechen, sowohl hierfür als auch für die Feuerlande.", sourceObjective = "Besorgt Euch den Zweig von Nordrassil beim Bernsteinflöz in der Boreanischen Tundra.", sourceObjectiveStatus = "unverified-source-field" }
quests[29240] = { id = 29240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notextrahierung", description = "Nun wieder zur anstehenden Aufgabe...\n\nIch bin mir sicher, dass die Vision im Nexus eine von Todesschwinges Illusionen ist, um unseren Schwarm in dieser schweren Zeit in Streit zu versetzen.\n\nDer Weltenbrecher würde nur noch stärker werden, wenn wir zu den Waffen greifen.\n\nDennoch, mir ist nicht ganz wohl bei der Sache, somit bin ich versucht einen Pfad der Vorsicht einzuschlagen.\n\nEs wäre weise, wenn ich mich mit Tarecgosa zurückziehen würde, bis die Zeit der Wahl gekommen ist.", sourceObjective = "Begleitet Kalecgos nach Kaltarra.\n\nSprecht mit ihm, wenn Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[29241] = { id = 29241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht den Götterbrecher", description = "<Blutschlächterin Zala zeigt auf den entfernten Tempel.>\n\nAls Jin'do das letzte Mal ins Jenseits befördert wurde, hat er als schwacher und gebrochener Schemen in der Geisterwelt überlebt.\n\nAber Jin'do hatte ja schon immer Macht über die Geister. Einen nach dem anderen hat er sie seinem Willen unterworf'n und mit jeder verschlungenen Seele is' er seinem Ziel näher gekomm'n, einen Riss in unsere Welt zu öffnen.\n\nJetzt is' er hier...\n\nDie Geister sind mit uns. Wir müss'n Jin'do ein Ende bereit'n.", sourceObjective = "Tötet Jin'do den Götterbrecher in Zul'Gurub auf heroischem Schwierigkeitsgrad.", completion = "<Blutschlächterin Zala greift sich an die Brust.>\n\nEs ist also getan. Das Blut unserer Brüder zu vergieß'n is' keine schöne Aufgabe. Die Stadt der Gurubashi hat jahrelang nur Tod und Hass erlebt.\n\nVielleicht is' es an der Zeit, dass der Dschungel Zul'Gurub zurückerobert und den Gestank des Todes von diesem Ort fortwäscht.\n\nBlut und Donner, Champion! Den Siame Quashi wirst du auf ewig als \"Blutschlächter\" bekannt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29242] = { id = 29242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbezahlbar mit Rabatt", description = "Hört zu, <mein Bester/meine Beste>. Ich kenne Euch nicht und Ihr kennt mich nicht, aber wo wir beide nun hier sind: Revilgaz wollte, dass ich etwas erwähne.\n\nVielleicht macht Ihr ja einen Spaziergang durch diese trollinfizierte Dschungelkalypse. Vielleicht findet Ihr ja rein zufällig das eine oder andere kostbare Trollartefakt. Vielleicht bringt Ihr es zu mir und ich lasse aus Versehen ein kleines Geschenk für Euch zurück.\n\nWenn Ihr es unbedingt wissen müsst, es ist für ein Projekt. Und nein, Ihr dürft nicht fragen, was das für ein Projekt ist.", sourceObjective = "Untersucht den Hort des Wahnsinns und findet das mysteriöse Schmuckstück der Gurubashi.", progress = "Na, habt Ihr etwas gefunden? Mir hängen nämlich langsam die Hosen auf Halbmast von all den Schätzen, auf die ich für Euch aufpasse.", completion = "Was habt Ihr denn da?\n\nEin merkwürdiges Schlangengötzenbild? Was soll ich denn damit anfangen? Etwa jemandem damit eins auf den Deckel geben und etwas stehlen, was tatsächlich was wert ist?\n\nDas Ding ist doch Ramsch!\n\n<Briney wirft das Schmuckstück ins Wasser.>\n\nNa dann danke für Eure \"Hilfe\". Hier habt Ihr Eure \"Belohnung.\"\n\nTrottel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29243] = { id = 29243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich ins Herz", description = "Einer von Ragnaros' Leutnants hat sich auf Ragnaros' Ebenen gezeigt. Es ist Zeit, zuzuschlagen. Hauptmann Saynna hat darum gebeten, dass Ihr dabei seid und ihr im Kampf beisteht.\n\nDorrzweig und einige andere werden sich bereits dem Kampf angeschlossen haben, wenn Ihr eintrefft. Ihr solltet Euch besser gleich in Richtung Nordwesten aufmachen und sie finden.", sourceObjective = "Tötet den Leutnant der Flamme.", completion = "Sehr gut gemacht, {name}! Das sollte sie erheblich hemmen.\n\nWenn wir das durchhalten, sollten wir den Kampf leicht zu Ragnaros selbst tragen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29245] = { id = 29245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das mysteriöse Samenkorn", description = "Eine kleine, trockene Eichel ist aus der Robe des Flammendruiden gefallen.\n\nWarum sollte ein Druide der Flamme so etwas mit sich herumtragen?\n\nVielleicht würde jemand in Malfurions Bresche sie gerne mal sehen.", sourceObjective = "Bringt die Eichel zu Avrilla in Malfurions Bresche in den Feuerlanden.\n\nBereitgestellter Gegenstand:", completion = "Faszinierend! Es scheint sich um eine Eichel zu handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[29246] = { id = 29246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindert den Schmerz", description = "Der Erzdruide kann ungeheure Schmerzen ertragen. Ich habe Opfer von Verbrennungen behandelt, die vierundzwanzig Stunden am Tag vor Schmerzen geschrien haben und ihre Verbrennungen waren nicht einmal halb so schlimm wie die, die Hamuul erlitten hat.\n\nNichtsdestotrotz kann ich sehen, dass er heute unter größeren Beschwerden leidet als normal. Bringt mir die Herzen der großen Feuerelementare im Südosten. Ich kann sie verwenden, um eine beruhigende Salbe für unseren Patienten herzustellen.", sourceObjective = "Sammelt 4 flammenumwundene Herzen von wutentbrannten Pyrolords.", progress = "Diese Herzen werden uns genau das geben, was Hamuul benötigt, um sich zu erholen.", completion = "Ich muss mich sofort daran machen, die Salbe zuzubereiten. Diese Reagenzien verlieren jede Minute an Wirkungskraft.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29247] = { id = 29247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verarzten der Wunden", description = "Wir haben hier beim Heiligtum ausreichend Vorräte an medizinischer Ausrüstung, aber wir dürfen nicht aus den Augen verlieren, dass wir uns im Krieg befinden. Hamuul ist nicht der Einzige, der Verbände benötigt.\n\nDie feurigen Ungetüme, die Sethrias Nest durchstreifen, tragen feuerresistente Bandagen, die Hamuul genauso gute Dienste leisten werden wie alle anderen Bandagen. Bringt mir diese Bandagen und ich werde sie dazu vorbereiten, sie dem Erzdruiden anzulegen.", sourceObjective = "Besorgt 4 sulfurgetränkte Bandagen von den feurigen Ungetümen in Sethrias Nest.", progress = "Es gibt Leute, die sagen, dass das Sulfur in diesen Bandagen heilende Wirkung hätte. Ich persönlich bin davon nicht überzeugt, aber für den unwahrscheinlichen Fall, dass dem doch so ist, bin ich willens, den Geruch zu ertragen.", completion = "Vielen Dank, {class}.\n\nIhr habt den Kriegsanstrengungen einen Dienst erwiesen. Opfer von Verbrennungen haben einen hohen Verbrauch an Verbänden und Hamuul ist da keine Ausnahme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29248] = { id = 29248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Druck lindern", description = "Nachdem er so furchtbare Verbrennungen erlitten hat, leidet der Erzdruide Hamuul unter Ödemen - Schwellungen des Körpergewebes. Es kostet seine Pfleger große Mühen, die Schwellungen so weit in Schach zu halten, dass er atmen kann.\n\nNormalerweise würden wir die Schwellung behandeln, indem wir Einschnitte ins Fleisch vornehmen, aber er ist zu schwach dafür, {name}. Ich kann ihn heute nicht heilen. Ich brauche Eure Hilfe.\n\nFlammenschürerschuppen helfen gegen die Schwellungen, aber man braucht davon eine ganze Menge.", sourceObjective = "Sammelt 100 Flammenschürerschuppen.", progress = "Habt Ihr die Schuppen? Ich zögere, dem Erzdruiden weitere Schnittwunden zuzufügen, aber wir müssen irgendwie die Schwellung bekämpfen.", completion = "Ihr seid barmherzig, {race}. Mit diesen vielen Schuppen werden wir ihm zumindest für einen Tag keine weiteren Schnitte zufügen müssen. Vielleicht sogar für zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[29250] = { id = 29250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Ihr seid keiner von den Zombies...\n\nEin Troll? Ich habe einen gesehen, direkt vor dem Ausbruch... Er hat uns gewarnt, gesagt, dass wir vorsichtig sein sollen... Aber es war zu spät.\n\nEuer Trollfreund ist nach Beutebucht gegangen, um sie zu warnen...", sourceObjective = "Begebt Euch nach Beutebucht und findet Bwembas Kontaktperson.", completion = "Ich werde Baron Revilgaz jetzt von der Zandalaribedrohung erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29251] = { id = 29251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Interessen Beutebuchts", description = "Also, {name}. Ihr habt uns schon gewaltig geholfen, aber das wird noch nicht reichen. Diese verrückten Trolle müssen aufgehalten oder zumindest von Beutebucht ferngehalten werden.\n\nIch werde jemanden losschicken, der das Geschehen im Auge behält, aber von Euch möchte ich, dass Ihr in Zul'Gurub eindringt und die Dinge in Bewegung setzt.\n\nIhr müsst mir zumindest etwas bringen, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", sourceObjective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", progress = "Habt Ihr etwas gefunden, {name}?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich.. gebt mir nur einen Moment, um die Belohnung zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29252] = { id = 29252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Interessen Beutebuchts", description = "Ich wurde von Baron Revilgaz aus Beutebucht hergeschickt, damit ich sicherstelle, dass diese Trollbedrohung aufgehalten wird. Oder dass sie zumindest vor den Toren von Beutebucht aufgehalten wird.\n\nIch will Taten und Ergebnisse sehen.\n\nIhr geht da jetzt für mich rein und veranstaltet ein Gemetzel.\n\nIhr geht da jetzt rein und sucht mir etwas, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", sourceObjective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", progress = "Habt Ihr etwas gefunden, {name}?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich.. gebt mir nur einen Moment, um die Belohnung zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29253] = { id = 29253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine glitzernde Beute", description = "Es gibt etwas Plündergut innerhalb der Statue auf der Janeirospitze, gleich nordwestlich von Beutebucht im Schlingendorntal.\n\nBegebt Euch zur Statue und nehmt Euren Preis an Euch, {class}.", sourceObjective = "Holt Euch Eure Belohnung aus einer Kiste in der Statue auf der Janeirospitze.", completion = "Endlich Beute!", sourceObjectiveStatus = "unverified-source-field" }
quests[29255] = { id = 29255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutharz", description = "Der Purpurpeitscher hat auf seinen Ranken einige aufbrechende Blasen entwickelt. Ohne Behandlung könnte dieser Zustand lebensbedrohlich werden.\n\nZum Glück produzieren die verkohlten Soldaten und Bezwinger in dieser Gegend eine wächserne Substanz mit Namen Glutharz, die die Qualen des Peitschers lindern könnte.\n\nBringt mir etwas von dieser Substanz und tötet diese garstigen Feuerelementare, während Ihr dabei seid.", sourceObjective = "Besorgt Euch 5 Portionen Glutharz von verkohlten Soldaten und Bezwingern.", progress = "Der Peitscher wächst sehr schnell.", completion = "Es riecht nicht besonders gut, aber es sollte dem Peitscher wieder auf die Beine helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29257] = { id = 29257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmolien, die ich stahl", description = "Wir haben eine neue Blumenart entdeckt, die in den Magmaquellen im Norden wächst. Erstaunlicherweise leben sie von reiner geschmolzener Lava!\n\nBitte geht und besorgt ein paar Exemplare dieser Pflanze für mich. Ich bin mir sicher, dass weitere Studien an diesen Pflanzen uns Aufschluss geben werden über unseren kleinen Freund hier.\n\nWo ich gerade von ihm spreche: er scheint ganz erpicht darauf zu sein, mit Euch zu gehen. Wollen wir hoffen, dass er sich benimmt.", sourceObjective = "Sammelt 8 Magmolien in den Magmaquellen im Norden.", progress = "Faszinierend! Je mehr Zeit ich in den Feuerlanden verbringe, desto mehr Hinweise erhalte ich, dass hier ein echtes Ökosystem am Werk ist.", completion = "Habt Dank, {name}. Ich werde diese Proben sofort analysieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29258] = { id = 29258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meteoritenjagd" }
quests[29261] = { id = 29261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Aman Voodoo", progress = "Der Erschaffer dieses Voodoohaufens ist während des Vorgangs gestorben. Wenn Ihr ihn jedoch abschließen könntet, würden die Geister Euch vielleicht beschützen...", completion = "Die Schrifttafel enthält den letzten Zauberspruch, um die Magie des Voodoohaufens an Euch und Eure Gruppe zu binden!" }
quests[29262] = { id = 29262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Voodoo", progress = "Dieser mächtige Haufen Voodoohexenkunst verströmt starkes Mojo...", completion = "Als Ihr die Tafel in den Voodoohaufen steckt, zerreißt ein markerschütternder Schrei die Stille." }
quests[29263] = { id = 29263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bittere Pille", description = "Soweit es mich betrifft, gibt es kein Problem, das nicht mithilfe von Bomben gelöst werden kann. Und wenn eine Bombe das Problem nicht beim ersten Versuch löst... dann muss man eben eine größere Bombe nehmen.\n\nEs gibt da also diesen großen Wurm, der Leute bei der Lavapfütze im Norden frisst. Haltet Ausschau nach Luftblasen, um ihn zu finden. Greift ihn an, bis er sich bereit macht, zuzubeißen, und platziert dann die Bombe vor ihm. Und dann könnt Ihr Euch zurücklehnen und das Feuerwerk genießen.\n\nHmm... es gab noch eine andere Sache, die ich sagen wollte... Ach ja! Lasst Euch nicht fressen.", sourceObjective = "Findet die Luftblasen des unterirdischen Magmawurms und besiegt ihn dann, indem Ihr ihn die bittere Pille schlucken lasst.", completion = "Ah, ich wusste, dass Rickets Bomben noch einmal nützlich sein würden. Es war nur eine Frage, ob wir etwas ausreichend Großes zum in die Luft sprengen finden würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29267] = { id = 29267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück im Unglück", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", sourceObjective = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29268] = { id = 29268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück im Unglück", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", sourceObjective = "Kümmert Euch um das Pantherjunge. Schließlich habt Ihr seine Mutter auf dem Gewissen.", completion = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29269] = { id = 29269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereint", description = "Ich war mit ihrer Sicherheit betraut, und doch war sie es, die sich für mich opferte.\n\nIch ertrage es nicht, sie zu verlieren, {name}. Ich muss Euch eine entscheidende Bitte stellen.\n\nNoch nie hat ein Sterblicher die Essenz eines wahren Drachen getragen, doch mit Eurer Erlaubnis würde ich eine Ausnahme machen.\n\nBitte, solange noch etwas Leben in ihr verweilt, erlaubt mir Tarecgosa an Euch zu binden.", sourceObjective = "Sprecht mit Kalecgos, um der Bitte zuzustimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29270] = { id = 29270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit drängt", description = "Tarecgosa ist an Euch gebunden, {name}, aber nur auf begrenzte Zeit. Die Macht eines Aspekts ist von Nöten, um ihre Essenz permanent zu versiegeln.\n\nMalygos' Nachfolger wird nicht vor der nächsten Mondfinsternis Azeroths bestimmt und der Bund, den Ihr mit ihr teilt wird nicht so lange überdauern.\n\nGlücklicherweise gibt es eine Möglichkeit, uns die nötige Zeit zu verschaffen. Es gibt mächtige Elemente, die die Dauer des Rituals verlängern können. Einige davon können in der Ebene des Feuers gefunden werden, mit der Ihr bereits vertraut seid.\n\nBesorgt sie, {class}, und haltet Tarecgosa bis zur Mondfinsternis aufrecht.", sourceObjective = "Sammelt 1000 Einheiten siedender Schlacke aus den Feuerlanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29271] = { id = 29271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ound for Warmer Weather" }
quests[29275] = { id = 29275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fandrals Methoden", description = "Die Druiden der Flamme... ein Orden von Druiden von dem Tholo und ich bis vor wenigen Wochen noch niemals gehört hatten. Und nun, unter der Führerschaft von Fandral Hirschhaupt, bedrohen sie den Erfolg unserer Mission mit ihrer Herrschaft über das Feuer.\n\nEs scheint, als würden sie einige Ausrüstungsgegenstände in den Feurigen Tiefen aufbewahren, im Nordosten. Wenn es uns gelingt, in den Besitz von einigen Teilen dieser Ausrüstung zu gelangen, haben wir vielleicht mehr Glück, wenn wir den Kampf zu Fandral tragen.", sourceObjective = "Beschafft Euch einen Flammendruidenstab, ein Flammendruidenzauberbuch, einen Flammendruidenreagenzienbeutel sowie einen Flammendruidengötzen.", progress = "Vertraut mir - alle Informationen, die wir hier sammeln, werden uns sehr dabei helfen, zu verstehen, was die Quelle für Fandrals Macht ist.", completion = "Anren, seht was {name} entdeckt hat! Das ist genau das, was wir brauchen!\n\nWir werden einige Zeit brauchen, um diese Ausrüstung anzusehen. In der Zwischenzeit ist Euch unser Dank gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[29276] = { id = 29276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammenspinnenkönigin", description = "Das Gelege der Witwe, im Nordosten, ist nach Beth'tilac benannt, der riesigen Königin der Flammenspinnen. Ihre Netze und ihr Gift sind eine nagende Bedrohung unserer Hauptoffensivkraft.\n\nWir glauben, wenn wir die Flammenspinnen hier an der Geschmolzenen Front studieren, dann können wir diese Information einsetzen, um einen Erfolg gegen Beth'tilac zu erzielen. Setzt alle Euch zur Verfügung stehenden Methoden ein, um Proben ihres Gifts und ihrer Spinnenseidenflüssigkeit zu sammeln und kehrt dann zu meinem getreuen Freund Anren zurück.", sourceObjective = "Sammelt 8 Proben Flammengift und 8 Proben sengende Spinnenseidenflüssigkeit.", progress = "Seid vorsichtig mit diesen Flüssigkeiten, {name}. Wir wollen doch nicht, dass etwas davon verschüttet wird.", completion = "Ihr seid ein echter Gewinn für unsere Sache, {name}. Tholo und ich danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29278] = { id = 29278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendes Obsidium", description = "Habt Ihr diese Feuerbälle gesehen, die vom Himmel kommen? Ich habe gesehen, wie einer von ihnen in die Felder im Norden eingeschlagen ist und das Gestein, was da gelandet ist, bestand aus purem Lebendem Obsidium!\n\nIch kann das Material benutzen, um ultra-robuste, hitzebeständige Rüstung und Waffen für unsere Truppen herzustellen. Könntet Ihr mir das Erz bringen?\n\nGeht zu den Magmaquellen und berührt einen der magnetischen Steine. Passt nur auf, wo Ihr steht, wenn der Feuerregen herunterkommt, und sammelt das Gestein ein, bevor es durch den Aufprall zerbricht.", sourceObjective = "Sammelt 10 Obsidiummeteoriten ein.", progress = "Wie geht es voran? Habt Ihr schon Meteoriten gefunden?", completion = "Fantastisch! Dann kann ich mich ja jetzt an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29279] = { id = 29279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befüllung des Mondbrunnens", description = "Wir haben diesen Mondbrunnen erschaffen, doch erfüllt er wenig Zweck, solange er noch nicht mit den Wassern des Brunnens der Ewigkeit gefüllt wurde.\n\nMit einem aktiven Mondbrunnen wäre es uns möglich, unsere Lebensmittelvorräte zu segnen, zu denen Ihr selbstverständlich Zugang bekommen würdet. Es sollte uns auch möglich sein, den Segen des Mondbrunnens zu nutzen, um Euch Schutz vor dem Feuer zu gewähren.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr mit Matookla am Heiligtum von Malorne sprechen. Sie wird in der Lage sein, für den sicheren Transport des heiligen Wassers zu sorgen.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Wie kann ich Euch helfen, {name}?", completion = "Natürlich. Ich werde mich sofort darum kümmern, dass die heiligen Wasser durch das Portal gebracht werden.\n\nDanke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29281] = { id = 29281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung", description = "Diesen Druiden fehlen die Werkzeuge, um ihre Aufgaben hier vernünftig zu erledigen. Ich hab' aber 'nen Kumpel beim Schrein des alten Hirschbocks, auf der anderen Seite des Portals. Wenn wir uns wiedertreffen sollten, dann hätten wir sicher ein bisschen Spielzeug, das wir gegen Ragni und seine Kumpane einsetzen könnten.\n\nNehmt einige der Abzeichendinger und geht damit zu Matookla. Fragt sie nach Ricket. Wir brauchen sie hier, damit wir ordentlich Ärger anzetteln können.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Ja, {name}?", completion = "Ich hatte mich schon gefragt, ob sich diese zwei nicht noch als nützlich erweisen würden. Sie schienen recht fehl am Platz zu sein, seitdem sie angekommen sind.\n\nIch habe Ricket vor ein paar Augenblicken hier in der Gegend gesehen. Ich werde sie mit Vergnügen mit Euch zusammen durch das Portal schicken. Auf der Seite wird sie auch weniger Gefahr laufen, das lokale Pflanzenleben in die Luft zu sprengen.\n\nLasst mich mal sehen... wo ist sie...?", sourceObjectiveStatus = "unverified-source-field" }
quests[29282] = { id = 29282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut bewaffnet", description = "Ricket sollte zusammen mit Damek bei Malfurions Bresche sein, wie von Euch erbeten. Ich bin mir allerdings nicht sicher, dass Ihr wirklich wisst, worauf Ihr Euch mit den beiden einlasst.\n\nWo wir gerade davon sprechen: Ihr solltet vermutlich mal nach ihnen sehen... um sicherzugehen, dass sie es noch nicht geschafft haben, den Wachenden Baum in die Luft zu jagen. So lange Ihr sie mit Elementaren beschäftigt haltet, sollte die Wahrscheinlichkeit von \"Unfällen\" an der Bresche dramatisch sinken.", sourceObjective = "Sprecht mit Ricket bei Malfurions Bresche.", completion = "Hey Ihr! Gut, Euch wiederzusehen!\n\nIch habe mich hier eigentlich schon ganz gut eingelebt! Es ist schön, mal wieder Zeit mit dem guten alten Damek zu verbringen. Ich hätte nie gedacht, dass ich mich mal so gut mit einem Zwerg verstehen würde, aber was die wichtigen Dinge angeht, da liegen er und ich auf derselben Wellenlänge.\n\nMacht Ihr mal Euer Ding und sorgt Euch nicht um uns. Wenn wir irgendwelches nettes Spielzeug für Euch haben, dann werden wir es Euch wissen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29283] = { id = 29283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rufen der Urtume", description = "Die Urtume warten in Hyjal. Die Feuerlande werden sich als gefährlicher Ort herausstellen, wenn man ihre... Zusammensetzung bedenkt, aber ihre Stärke wird uns sehr von Nutzen sein, wenn wir uns Ragnaros' Leutnants stellen müssen.\n\nSammelt Eure Abzeichen und sprecht mit Ahnenzweig am Heiligtum von Malorne. Wenn sie an unserer Seite marschieren sollen, so wäre er derjenige, der sie durch das Portal anführen würde.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Seid gegrüßt, junges Wesen.", completion = "Ich verstehe. Wir sind bereit. Wir werden uns dem Zug anschließen und Euch auf der am weitesten entfernten Seite des Portals treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29284] = { id = 29284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe der Urtume", description = "Die Urtume haben den Wert Eurer Weisheit erkannt und sich bei Malfurions Bresche niedergelassen. Ihr solltet Ahnenzweig aufsuchen. Ich bin sicher, er würde sich freuen, von Euch zu hören.", sourceObjective = "Sprecht mit Ahnenzweig bei Malfurions Bresche.", completion = "Ihr habt einen weisen Zeitpunkt ausgewählt, um zu uns zu kommen, {class}. Ich war besorgt gewesen, ob wir in diesem Reich gegen die Elemente bestehen könnten, aber der Schutz des Wachenden Baums hat sich als mehr als ausreichend erwiesen.\n\nWir werden alles tun, um Euch in Euren Bemühungen zu unterstützen. Dorrzweig hat sich mit Euren anderen Verbündeten getroffen und bespricht mit ihnen Wege, einige von Ragnaros' Leutnants in die Ecke zu treiben. Ihr solltet mit ihnen sprechen, wenn die Zeit gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29289] = { id = 29289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen einer Mutter", description = "Wenig überraschend hat die Matriarchin Anstoß daran genommen, dass wir ihre Jungen für unsere eigenen Zwecke ausgebildet haben. Verständlich... und eigentlich ein wenig tragisch. In dieser Sache sind wir die Bösen.\n\nJetzt ist aber nicht die Zeit, über solche Dinge nachzudenken. Diese Kreaturen sind Wesen aus Feuer und bei mehr als einer Gelegenheit haben sie Leben in unseren Reihen gefordert. Nun da ihre Matriarchin verärgert ist, ist die Gefahr immens gewachsen.\n\nIch brauche jemanden, der ihren Zorn besänftigt, und ich fürchte, dass Ihr dazu am fähigsten seid.", sourceObjective = "Bezwingt die Feuerfalkenmatriarchin.", sourceObjectiveStatus = "unverified-source-field" }
quests[29291] = { id = 29291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Schirm, Charm und Bomben" }
quests[29292] = { id = 29292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenfeuer" }
quests[29294] = { id = 29294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "nimate Embers" }
quests[29298] = { id = 29298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrußtes Medaillon", description = "Auf der Oberseite dieses Medaillons sind einige kleine, blattförmige Schnitzereien zu sehen, aber alle anderen Details haben sich mit der Zeit abgescheuert oder sind durch Feuer verbrannt worden. Es scheint druidischer Natur zu sein.\n\nDie meisten Druiden besuchen die Mondlichtung während ihrer Ausbildung. Wenn Euch jemand dabei helfen kann, die Herkunft dieses Medaillons herauszufinden, dann ist das Rabine Saturna in Nachthafen.", sourceObjective = "Bringt das verrußte Medaillon zu Rabine Saturna in Nachthafen auf der Mondlichtung.", progress = "Ja, junger {race}?", completion = "Was haben wir denn da? Eine Halskette? Nein, ein Medaillon...\n\nOh je...", sourceObjectiveStatus = "unverified-source-field" }
quests[29299] = { id = 29299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manche mögen's heiß", description = "Ich bin in meinen Studien vorangekommen, {name}. Basierend auf den Dingen, die wir in der lokalen Flora beobachtet haben, ist es durchaus möglich, dass Euer Peitscher auch supererhitzte Flüssigkeiten als Hauptnahrungsquelle verträgt.\n\nIch hätte gerne, dass Ihr mir bei einem kleinen Experiment helft. Die Glutspeiskorpione, die in den Magmaquellen im Norden hausen, versprühen im Kampf brennende Feuerlachen.\n\nNehmt den Peitscher und beobachtet seine Reaktion auf die Glutlachen der Skorpione.", sourceObjective = "Beobachtet den Purpurpeitscher, wenn er von 6 Glutlachen trinkt. Glutlachen entstehen durch den Kampf gegen Glutspeiskorpione.", completion = "Hat es funktioniert? Meine Theorie war also korrekt?", sourceObjectiveStatus = "unverified-source-field" }
quests[29302] = { id = 29302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufdecken verborgener Geheimnisse", description = "Die Initialen auf dem Medaillon scheinen verblasst zu sein, aber ich kann eine Macht darin spüren, die auf nur einen möglichen Besitzer schließen lässt:\n\nLeyara, die Druidin der Flamme.\n\nTretet zurück und wir werden sehen, welche Überraschungen dieses Medaillon bereithält.", sourceObjective = "Beobachtet die in dem verrußten Medaillon gespeicherten Erinnerungen.", completion = "Wenn Leyara den Krieg der Sandstürme miterlebt hat, dann ist es wahrscheinlich, dass sie Fandral kannte - und seinen verstorbenen Sohn, Valstann - und zwar sehr viel näher, als wir jemals vermutet hätten.\n\nEs scheint, dass Eure Reise hier noch nicht endet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29303] = { id = 29303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tragödie und Familie", description = "Es war sehr einsichtsvoll von Euch, mir dieses Medaillon zu bringen, {name}. Ich bin einer der wenigen, die wissen, wo Valstanns Leichnam begraben ist.\n\nIhr findet seine letzte Ruhestätte auf einem kleinen Friedhof, südöstlich von Astranaar im Eschental. Bringt dieses Medaillon zu dem Ort und vielleicht eröffnet es Euch weitere Erinnerungen.\n\nLebt wohl, {name}, und viel Glück für Eure Reise.", sourceObjective = "Bringt das verrußte Medaillon zu dem nachtelfischen Grab in der Nähe von Astranaar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[29304] = { id = 29304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde des Krieges", description = "Unsere Truppen werden von entfesselten Monstrositäten in die Knie gezwungen - Aschenhunde aus den geschmolzenen Tiefen.\n\nDiese Hunde fürchten nichts und niemanden und werden nicht innehalten, bis ihr Blutdurst befriedigt ist. Unsere Streitkräfte können sie gerade so zurückhalten.\n\nGeht und schließt Euch den Verteidigern auf den Aschenfeldern oder im Geschmolzenen Strom an. Vielleicht gelingt es Euch, ihre Anzahl ein wenig zu reduzieren.", sourceObjective = "Tötet 5 Aschenhunde oder uralte Aschenhunde.", completion = "Gut, {class}. Der Feind mag hart sein, aber Ihr habt heute bewiesen, dass Ihr härter seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[29310] = { id = 29310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trendwende", description = "An dem Tag, an dem Leyara Hamuul angriff, hat sie in der Nähe von einigen Ruinen am Hyjal gewartet, nordwestlich des Geheilten Hyjal. Sie hat sich zu der Zeit seltsam verhalten: gefasst, ruhig und mit Blick in die Ferne. Möglicherweise ist der Ort für sie wichtig.\n\nDas Medaillon könnte vielleicht reagieren, wenn es an diesen Ort gebracht wird.", sourceObjective = "Bringt das verrußte Medaillon zu dem kleinen Grabstein bei Leyaras Trauer beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29313] = { id = 29313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des perfekten Kimchis", description = "Meine Familie stellt seit Generationen das beste Kimchi in ganz Darnassus her, {name}. Das Geheimnis ist eine ganz einfache Sache, aber sie macht den ganzen Unterschied.\n\nWir vergraben die Krüge im Boden, bis der Inhalt bereit ist, serviert zu werden, und die letzte Ladung hat gerade diesen Punkt erreicht. Ihr könnt die Krüge überall in der Stadt in Erdhügeln vergraben finden. Würdet Ihr mir helfen, sie einzusammeln, solange ihr Inhalt genau richtig ist?", sourceObjective = "Findet 8 vergrabene Kimchikrüge in Darnassus.", progress = "Habt Ihr die Krüge gefunden?", completion = "Habt Dank, {name}. Ich hätte sie nie alle rechtzeitig finden können und es wäre doch schade gewesen, so viel gutes Kimchi zu verpassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29314] = { id = 29314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenkt der Vorfahren", description = "Die Lebenden sind nicht die einzigen, die Nahrung brauchen. Eine meiner Pflichten besteht darin, die Reiskuchen zuzubereiten, die den Vorfahren dargebracht werden. Normalerweise hat meine oberste Schülerin die Ehre, die Kuchen zum Tempel des Mondes zu bringen, damit sie dort gesegnet werden, und sie dann den Vorfahren darzubieten. Würdet Ihr, da sie heute nicht in der Stadt ist, diese Pflicht an ihrer Stelle übernehmen?", sourceObjective = "Sammelt die gesegneten Reiskuchen aus dem Tempel des Mondes ein.", progress = "Dies ist der Schrein, von dem der Ausbilder gesprochen hat.", completion = "<Ihr plaziert die Reiskuchen um den Schrein herum, der anfängt, sanft zu leuchten. Euch überkommt ein mildes Gefühl der Dankbarkeit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29315] = { id = 29315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungourmet", description = "Manche Köche beschweren sich darüber, dass unsere geliebte Unterstadt nicht mit den nötigen Zutaten aufwarten kann, um wahrhaftig köstliche Speisen zuzubereiten.\n\nWas für jammernde Einfaltspinsel. Dabei gibt es hier doch solche Köstlichkeiten!\n\nSammelt einige der ranzigen, schleimigen Abflusskappen, die entlang der Nordwestkanäle der Unterstadt wachsen und bringt sie zu mir.", sourceObjective = "Besorgt 12 Abflusskappen. Liefert die Pilze bei Eunice Burch in Unterstadt ab.", progress = "Habt Ihr genügend Abflusskappen finden können?", completion = "Die riechen ja einfach nur widerlich. Perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29316] = { id = 29316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundnahrungsmittel", description = "Es gibt bestimmte Dinge, die jeder braucht, vom Koch im kleinsten Haushalt bis zum obersten Küchenchef. Eines der wichtigsten Grundnahrungsmittel der Stadt ist Reismehl. Die meisten Familien haben mindestens einen Korb Reis in ihrem Haus und das gilt genauso für die Bewohner der Terrassen der Handwerker und der Händler.\n\nIch trage meinen Schülern oft auf, dabei zu helfen, Reis in Mehl zu verwandeln, da es eine gute Übung und eine Endlosaufgabe ist. Warum versucht Ihr es nicht einmal?", sourceObjective = "Helft den Bewohnern der Terrasse der Handwerker und der Terrasse der Händler Reis in Mehl zu verwandeln, indem Ihr den Inhalt der Reiskörbe zermahlt.", completion = "Nur durch viel Fleiß und Mühe können wir sicherstellen, dass es genügend Mehl für alle gibt. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29317] = { id = 29317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischkopp", description = "Es hat einen... Vorfall mit einer Orcwache und einer von Apothekermeister Faranells Monstrositäten gegeben.\n\nOffenbar hat der Aufseher der Kor'kron ihr kurzerhand den Kopf abgeschlagen und ihn in den Schleim getreten.\n\nFaranells Lehrlinge suchen schon seit Stunden danach, können das Ding aber einfach nicht finden. Würdet Ihr versuchen, nach ihm zu angeln? Ich bin sicher, dass der alte Knabe sehr dankbar wäre.", sourceObjective = "Armand Kromwell möchte, dass Ihr für Apothekermeister Faranell einen abgetrennten Monstrositätenkopf aus den Kanälen von Unterstadt angelt.", progress = "Ihr habt nicht rein zufällig einen abgetrennten Monstrositätenkopf gesehen, oder...?", completion = "Ah! DA ist er ja! Wie habt Ihr ihn nur gefunden?\n\nNun, ganz gleich. Meine Schüler waren nicht in der Lage, den Kopf zu finden, obwohl sie stundenlang im Schleim herumgeplantscht haben. Aber dabei haben sie IMMERHIN diesen Beutel mit Glitzerkram gefunden... vielleicht könnt Ihr ja mit dem Inhalt etwas anfangen?\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29318] = { id = 29318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rippchen für die Schildwachen", description = "Einer meiner Verantwortungsbereiche umfasst die Verpflegung der Schildwachen von Darnassus, wenn sie im Dienst sind. Diese Aufgabe kostet Zeit, aber es ist eine, die ich gerne erledige. Würde es Euch etwas ausmachen, mir beim heutigen Essen zu helfen? Nehmt einfach diese Rippchen, bereitet sie in einem Herd oder über einem Feuer zu und verteilt sie unter den Schildwachen in der Stadt.", sourceObjective = "Benutzt die rohen Rippchen in der Nähe eines Herdes oder Lagerfeuers, um sie zu kochen und benutzt sie dann, um 5 Schildwachen von Darnassus zu verpflegen.", completion = "All diese Schildwachen zu verköstigen ist mit Eurer Hilfe viel einfacher. Diesmal musste sich niemand für sein Essen anstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29319] = { id = 29319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaulquappen des Todes", description = "Einige unserer Apotheker haben es sich zur Gewohnheit gemacht, ihren etwas bedenklicheren chemischen Müll in den Stillwassertümpel zu kippen und... nun, sagen wir einfach, dass niemand so genau wissen möchte, wie groß mutierte fleischfressende Kröten werden können.\n\nWärt Ihr bereit, ein paar riesige fleischfressende Kaulquappen zu fangen, bevor es soweit kommt? Fasst sie nur besser nicht mit bloßen Händen an.", sourceObjective = "Armand Kromwell in Unterstadt möchte, dass Ihr ihm 8 riesige fleischfressende Kaulquappen bringt.", progress = "Habt Ihr ein paar mutierte Kaulquappen finden können? Ihr solltet sie besser nicht mit bloßen Händen anfassen.", completion = "Ausgezeichnete Arbeit, {name}. Ich sorge dafür, dass sie sofort... verwahrt werden.\n\nWas könnten unsere wunderbaren Apotheker denn auch mit einer Armee monströser, giftspuckender, fleischfressender Superkröten anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29320] = { id = 29320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein toller Hecht", description = "Ihr habt doch schon im Blendwassersee geangelt, oder?\n\nDer größte Fang in dem See ist, einen der riesigen leichengefütterten Hechte an Land zu ziehen. Sie beißen allerdings nur bei einer ganz besonderen Ködersorte an... Leichenwürmer.\n\nSucht bei den Gräbern im Innenhof an der Oberfläche. Dort solltet Ihr welche finden können.", sourceObjective = "Grabt einen Leichenwurm im Innenhof der Ruinen von Lordaeron aus und benutzt ihn als Köder um einen leichengefütterten Hecht zu fangen. Leichengefütterte Hechte gibt es im Blendwassersee, nordöstlich von Unterstadt.", progress = "Schon den Hecht gefangen?", completion = "Das ist ein toller Hecht, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29321] = { id = 29321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheltaucher", description = "Es scheint, als würden alle, die ich kenne, Muscheln lieben, aber ich kann ihren Anblick nicht ertragen! Sie riechen schlecht und sind schleimig und um sie zu ernten, muss man im Matsch graben. Da würde ich einer Angel und ein bisschen Köder doch jeden Tag den Vorzug geben.\n\nTrotzdem möchte ich meinen Bruder mit einem Eimer frischer Muscheln überraschen. Euch winkt eine Belohnung, wenn Ihr Euch bereit erklärt, mir diese Muscheln zu beschaffen.\n\nGeht einfach durch das Portal nach Rut'theran und sucht in den seichten Stellen am Ufer nach Muscheln.", sourceObjective = "Sammelt 10 Teldrassilmuscheln von den Ufern in der Nähe von Rut'theran.", progress = "Habt Ihr genug Muscheln gefunden?", completion = "Igitt, die sehen so eklig aus, aber mein Bruder mag sie am liebsten. Danke, dass Ihr mir diese unangenehme Aufgabe abgenommen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29322] = { id = 29322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleim-Time", description = "Es braucht schon eine ganz besondere Art von Angler, um die Schätze der blubbernden Schleimkanäle von Unterstadt wertzuschätzen. Meint Ihr, Ihr könnt ein paar der zuckenden Schleimschimmel einsammeln, die dort unten herumkriechen?\n\nIhr könnt versuchen, sie zu angeln, aber sie sind verschlagen; vielleicht wäre es einfacher, ein Schleimbad zu nehmen und sie einfach zu packen.\n\nDenkt daran, dass sie uns nur lebendig und intakt etwas nützen... Wer möchte schon gern tote Schleimschimmel essen?! Widerwärtig.", sourceObjective = "Sammelt 10 zuckende Schleimschimmel. Liefert sie bei Armand Kromwell in Unterstadt ab.", progress = "Gar nicht so einfach zu fangen, was?", completion = "Diese Schleime sehen perfekt aus. Ich schicke sie auf den Weg zu Eunice, damit sie sie zubereitet. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29323] = { id = 29323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wir haben die meisten unserer Lebensmittelvorräte benutzt, um diejenigen zu versorgen, deren Häuser und Lebensgrundlagen zerstört wurden. Wenn wir unsere Vorräte nicht wieder aufstocken, werden wir alle in Gefahr sein, wenn das nächste Mal ein schlimmer Sturm oder eine Invasion der Horde über uns hereinbricht.\n\nVielleicht seid Ihr bereit, mir dabei zu helfen, unsere Bestände an Seefelchen wieder aufzufüllen. Ihr könnt sie überall in Darnassus fangen und sobald sie getrocknet sind, halten sie sich, bis sie gebraucht werden.", sourceObjective = "Fangt 5 Seefelchen, indem Ihr in Darnassus angelt.", progress = "Wenn all unsere Fischer mit anpacken, dann wird es nicht lange dauern, bis wir unsere Vorräte wieder aufgefüllt haben.", completion = "Die sind prächtig! Danke, {name}. Ich hänge sie zum Trocknen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29324] = { id = 29324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anhänger der Schwester", description = "Habt Ihr schon Schwester Aquinne kennengelernt? Sie und ich sind gemeinsam in Dolanaar aufgewachsen und sie ist vor kurzem in der Stadt angekommen, um im Tempel des Mondes ausgebildet zu werden. Wir haben eine Bootsfahrt gemacht, aber der ungeschickte Ruderer hat das Boot zum Kentern gebracht!\n\nAls wir wieder am Ufer waren, war Aquinnes Anhänger verschwunden. Die Seen von Darnassus sind voll von riesigen Welsen, die alles was glänzt verschlucken.\n\nIch habe ohne Pause nach ihnen geangelt und gehofft, dass ich einen mit ihrem Anhänger finde. Wollt Ihr mir vielleicht helfen?", sourceObjective = "Erhaltet Aquinnes Mondanhänger aus dem Magen eines riesigen Welses. Ihr solltet sie an jeder Angelstelle in Darnassus fangen können.", progress = "Konntet Ihr Aquinnes verlorenen Anhänger finden? Ich muss schon etwa fünfzig dieser Monster gefangen haben und habe nicht die geringste Spur!", completion = "<Astaia nimmt Euch den Anhänger ab.>\n\nUnter all dem Schleim und Anlauf glaube ich, es wiederzuerkennen! Aquinne wird sich so freuen, es wiederzubekommen... natürlich nachdem ich es gründlich gereinigt habe. Ich kann Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29325] = { id = 29325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein glitschiger Snack", description = "Habt Ihr schon einmal Oktopusfleisch gegessen? Es ist etwas gewöhnungsbedürftig, aber es ist mein Leibgericht! Ich kenne sogar Leute, die die Dinger am Stück und lebendig essen!\n\nIch habe nicht vor, das bald auszuprobieren, aber mir sind gerade die frischen Oktopusse ausgegangen. Helft Ihr mir, neue zu bekommen? Sie leben im seichten Wasser an der Küste von Rut'theran.", sourceObjective = "Sammelt 6 Babyoktopusse aus dem seichten Wasser in der Nähe von Rut'theran.", progress = "Es ist unmöglich, Oktopusse mit einer Rute zu fangen. Ihr müsst sie einfach packen!", completion = "Die werden köstlich sein, das weiß ich jetzt schon! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29326] = { id = 29326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nordrassilgipfeltreffen", description = "Hallo, {class}! Meine Brüder und Schwestern vom Irdenen Ring haben Gutes über Eure Taten nach dem Kataklysmus zu berichten gewusst. Doch noch immer muss vieles getan werden, wenn diese zerbrochene Welt geheilt werden soll.\n\nBegleitet mich ein paar Schritte. Vorbereitungen für eine Zeremonie sind im Gange, für ein Ritual, von dem ich hoffe, dass es der Wendepunkt in unserem Kampf gegen den Schattenhammer darstellen wird.\n\nSobald alles abgeschlossen ist, werdet Ihr das Wort über unseren Triumph hier in die Welt tragen können.", sourceObjective = "Sprecht mit Thrall unter dem Weltenbaum am Hyjal und beobachtet die Zeremonie des Irdenen Rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[29327] = { id = 29327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Zweifel", description = "Ich kenne denjenigen, nach dem Ihr sucht... aber ich weiß nicht, ob es weise von Euch ist, ihm zu folgen. Er hat sich selbst in den Zyklon gestürzt. Die Winde zehren nun an seinem Körper und seinem Geist, zweifellos lassen sie nichts zurück als Fetzen und Zweifel.\n\nHinter ihm herzujagen würde Euch nur demselben Schicksal aussetzen. Der schneidende Wind lässt nichts unberührt.\n\nIhr seid gewarnt worden. Was habt Ihr jetzt vor?", sourceObjective = "Sprecht mit Zyklonas, um eine sichere Passage zu Thrall zu bekommen. Kämpft dann mit den Windelementaren, die ihn peinigen, bis er frei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29328] = { id = 29328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Verlangen", description = "Noch einmal, {class}, ich schaffe es nicht ohne Eure Hilfe. Ich werde versuchen, den Sturm zu besänftigen, aber Ihr werdet die instabilen Elementare zurückdrängen müssen, die darum herumwirbeln. Nur dann können wir Go'el befreien!", sourceObjective = "Vernichtet die Fluten des Verlangens und die Wirbel des Verlangens in der Nähe des Wirbelnden Abgrunds, bis Thrall aus ihren Fängen befreit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29329] = { id = 29329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Geduld", description = "Mit dem Segen der Steinmutter kann ich uns dahin bringen, wo Go'el gefangengehalten wird.\n\nWir müssen vorsichtig sein. Der Schattenhammer verfügt überall über Agenten. Helft mir, sie zurückzuhalten, während ich versuche, zu Go'el durchzukommen!\n\nSprecht mit mir, wenn Ihr bereit seid und ich werde Euch zu ihm bringen.", sourceObjective = "Sprecht mit Aggra, wenn Ihr bereit seid, Thrall zu helfen. Bezwingt dann die Elemente und Kernsteine der Geduld, die ihn gefangenhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29330] = { id = 29330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Zorn", description = "Die Totems, {name}! Wir müssen sie aktivieren oder Go'el ist verloren!\n\nTötet die Elementare neben jedem meiner Totems, die an den Kanten dieses Plateaus platziert sind. Sobald alle vier Totems aktiviert sind, sollte es uns möglich sein, das letzte Stück von Go'els Seele zu befreien!", sourceObjective = "Tötet Feuerelementare neben Aggras Lufttotem an der westlichen Kante des Plateaus, bis es aktiviert ist. Macht dann bei Aggras Wassertotem, Aggras Erdtotem und Aggras Feuertotem weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29331] = { id = 29331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Das Gelübde", description = "Bevor er durch das Portal zum Hyjal trat, hat Thrall Euch gebeten, ihm zu folgen. Es gibt da etwas, von dem er möchte, dass Ihr es seht.", sourceObjective = "Sprecht mit Thrall bei Nordrassil auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29332] = { id = 29332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckere Lilien", description = "Die Lilien, die um den Stillwassertümpel herum wachsen, lassen sich zu einer köstlichen Suppe verkochen.\n\nNun ja... \"köstlich\" in dem Sinne, dass nicht sofort jedem Orc schlecht wird, der sie trinkt.\n\nWarum sammelt Ihr nicht ein paar für mich, hmmm? Gebt nur gut auf die riesigen fleischfressenden Kaulquappen Acht.", sourceObjective = "Besorgt 10 Stillwasserlilien. Liefert die Pflanzen bei Eunice Burch in Unterstadt ab.", progress = "Habt Ihr genügend Stillwasserlilien finden können?", completion = "Ah, so eine üppige Ladung Lilien. Bravo! Ich koche sie sofort ein...", sourceObjectiveStatus = "unverified-source-field" }
quests[29333] = { id = 29333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneckt lecker!", description = "Die Orcwachen beschweren sich ständig über fade, schimmlige Kost in Unterstadt - als ob WIR etwas dafür könnten, dass sie sich nicht von Pilzen und alten Leichen ernähren können - also finde ich, dass es an der Zeit ist, dass sie herausfinden, was für exotische Köstlichkeiten wir zubereiten können, wenn wir wollen.\n\nSammelt ein paar Süßwasserschnecken aus dem Blendwassersee und ich zeige ihnen, was eine wahre kulinarische Meisterin zaubern kann.", sourceObjective = "Sammelt 8 Blendwasserschnecken. Liefert sie bei Eunice Burch in Unterstadt ab.", progress = "Schon die Süßwasserschnecken gesammelt?", completion = "Ihr müsst ein guter Schwimmer sein... Ich kann höchstens Toter-Mann spielen.\n\nWie dem auch sei, Ihr habt da ein hervorragendes Bündel Schnecken gesammelt. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29334] = { id = 29334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahres Schabsal", description = "Bei all dem Gemecker, das diese Aufseher der Kor'kron für die Verpflegung in Unterstadt übrig haben, gibt es eine Sache, die sie schaufelweise essen: der dreifach gewürzte Knuspereintopf meiner Schwester.\n\nWeil er so beliebt ist, gehen ihr ständig die Zutaten aus. Würdet Ihr ein paar zu ihr zum Wagen bringen, aus dem sie den Eintopf verkauft?\n\nÜberall in der Stadt werdet Ihr Fallen finden; bringt einfach deren Inhalt zu Audrey und sie kümmert sich um den Rest!", sourceObjective = "Beschafft 20 träge Kakerlaken. Liefert die Insekten bei Chefköchin Audrey in Unterstadt ab.", progress = "Ich nenne meine kleinen Fallen \"Kakerlabinen\".\n\nKakerlaken spazieren hinein, sie spazieren aber nicht wieder heraus.", completion = "Gerade noch rechtzeitig bevor meine Vorräte erschöpft waren. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[29335] = { id = 29335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die beißenden Winde", description = "{class}, ich weigere mich zu glauben, dass mein Go'el für immer verloren ist. Sein Geist ist über die Elementarebene zerstreut worden. Sollte auch nur ein Teil von ihm noch existieren, dann können wir ihn finden, ich brauche allerdings Eure Hilfe.\n\nWir werden mit der Ebene der Luft beginnen.\n\nSprecht mich erneut an und wir werden gemeinsam zum Vortexgipfel reisen. Wir müssen mit einem Elementar namens Zyklonas sprechen. Ein launischer Geselle, aber im Reich der Luft sieht er alles. Wenn mein Liebster dort sein sollte, so wird Zyklonas wissen, was mit ihm geschehen ist.", sourceObjective = "Sprecht mit Zyklonas auf dem Felsen des Südwinds in Uldum.", sourceObjectiveStatus = "unverified-source-field" }
quests[29336] = { id = 29336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die drängenden Fluten", description = "Go'el muss sich auf der Ebene des Wassers befinden... im Meeresschlund selbst! Mich fröstelt, wenn ich mir vorstelle, was ihn dort erwartet.\n\nFindet den Elementar Hydrius, in der Nähe des Wirbelnden Abgrunds. Er weiß von Go'el und sympathisiert mit unserem Kampf gegen Ragnaros. Wenn Euch jemand dort helfen kann, dann er.\n\nIch werde Euch unter den Strömen Vashj'irs treffen, {race}...", sourceObjective = "Sprecht mit Hydrius beim Wirbelnden Abgrund in den Abyssischen Tiefen von Vashj'ir.", sourceObjectiveStatus = "unverified-source-field" }
quests[29337] = { id = 29337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die beständige Erde", description = "Die Zeit ist knapp! Mein Liebster liegt in Tiefenheim. Ich werde uns dorthin bringen, sobald Ihr bereit seid, und wir werden mit Therazane, der Steinmutter, sprechen.", sourceObjective = "Sprecht mit Therazane bei Therazanes Thron in Tiefenheim.\n\nAggra kann Euch vom Wirbelnden Abgrund aus zu Therazanes Thron teleportieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29338] = { id = 29338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die unnachgiebige Flamme", description = "Wir müssen nun zu den Feuerlanden reisen. In diesem Reich kann Go'els brennender Geist so fürchterlich wie Ragnaros selbst werden! Macht Euch bereit, da er allein in einer feindlichen Welt sein wird.\n\nSprecht mich an, wenn Ihr bereit seid... und mögen die Vorfahren uns beschützen!", sourceObjective = "Sprecht mit Aggra auf dem Nimbusrücken in Tiefenheim, um eine Passage in die Feuerlande zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29339] = { id = 29339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29340] = { id = 29340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29341] = { id = 29341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29342] = { id = 29342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisangeln", description = "Die leckersten Fische leben in den kalten Gewässern Dun Moroghs, {name}, lasst Euch da mal nichts anderes erzählen! Mein Favorit, und am beliebtesten in Eisenschmiede, ist der Seesaibling, der aus den Ländern unserer Ahnen kommt.\n\nIch möchte ihn als Eisenschmiedes Geschenk an die Welt bezeichnen!\n\nWarum versucht Ihr nicht mal selbst, ein paar davon zu fangen? Der beste Ort, um diesen Fisch zu finden, ist im Helmsbettsee, im östlichen Teil von Dun Morogh.", sourceObjective = "Fangt 5 Seesaiblinge, indem Ihr im Helmsbettsee in Dun Morogh angelt.", progress = "Habt Ihr schon versucht, diese Saiblinge zu fangen?", completion = "Sie sind wunderschön, {name}! Ich glaube, Ihr habt jetzt langsam den Dreh raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29343] = { id = 29343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Ich bin mir sicher, dass Ihr inzwischen schon mal vom alten Eisenkiefer gehört habt, dem berühmtesten und am schwersten fassbaren Fisch in den Gewässern von Eisenschmiedes Düsterem Viertel. Nun, in seinen vielen Lebensjahren war er dafür verantwortlich, dass jede Menge Nachkommen das Licht der Welt erblickten. Lasst Euch nicht von dem Namen \"Junger Eisenkiefer\" täuschen, {name}, diese Jungfische sind genauso clever wie ihr Vater, ihnen mangelt es nur ein wenig an Erfahrung.\n\nMit Können und Geduld wird es Euch sicher gelingen, einen zu fangen, und wenn es so weit ist, dann bringt ihn zum Museum in Eisenschmiedes Bibliothek und stellt ihn aus, damit ihn alle sehen können!", sourceObjective = "Fangt einen jungen Eisenkiefer in Eisenschmiedes Düsterem Viertel und stellt ihn in der Bibliothek neben der leeren Plakette aus.", completion = "Gut gemacht, {name}! Vielleicht wird Euer Fang ja mehr Zwerge dazu inspirieren, das Angeln anzufangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29344] = { id = 29344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fische für Squirky", description = "Hab ich Euch schon meinen Begleiter Squirky vorgestellt? Ich bringe ihm bei, wie man angelt, so richtig mit allen Schikanen! Bisher habe ich ihn mit Elritzen gefüttert, die ich aus dem Teich in diesem Viertel gefischt habe.\n\nVielleicht wollt Ihr es ja mal versuchen? Werft einfach Euren Köder in dem Teich da drüben aus und füttert Squirky mit den Elritzen, die Ihr rauszieht. Er wird Euch für immer lieben!", sourceObjective = "Angelt 3 blinde Elritzen aus dem Teich im Düsteren Viertel und verfüttert sie an Squirky.", completion = "Ihr habt gute Arbeit geleistet. Squirky sieht zufrieden aus und ich hatte Zeit, ein paar neue Köder zu basteln. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29345] = { id = 29345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tümpelschrecken", description = "Ein Goblinbesucher, der es sicher nur gut meinte, hat Azsharaschlangenköpfe in unseren Gewässern ausgesetzt und die überrennen jetzt unseren Teich.\n\nIch bitte Euch, wenn Ihr ein paar von diesen gefräßigen Raubfischen fangen könnt, bevor sie alle Kleinfische und Matschschnapper in Donnerfels gefressen haben, wäre ich sehr dankbar.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 8 Azsharaschlangenköpfe aus dem Teich in Donnerfels.", progress = "Konntet Ihr schon ein paar Azsharaschlangenköpfe fangen?", completion = "Gut gemacht, {name}. Alle Angler von Donnerfels müssen mit anpacken, damit sich diese boshaften Geschöpfe nicht in Mulgores Gewässern ansiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29346] = { id = 29346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ring sie zu knechten", description = "Einer der Verlassenen aus den Teichen der Visionen ist an mich herangetreten und hat mir gesagt, dass sein Ring von einem blinden Höhlenfisch in den dortigen Teichen verschluckt worden ist.\n\nEs könnte auch sein Finger gewesen sein. So richtig verstanden habe ich ihn nicht; sein Kiefer hat sich nicht bewegt und sein Orcisch war nicht besser als mein eigenes.\n\nWie dem auch sei, ich dachte mir, dass wir unseren ungewöhnlichen Gästen einen Gefallen tun könnten und Höhlenfische ausnehmen könnten, bis wir den Ring - oder den Finger - gefunden haben.\n\nWürdet Ihr mir helfen?", sourceObjective = "Angelt einen blinden Höhlenfisch aus den Teichen der Visionen in Donnerfels. Wenn Ihr einen gefangen habt, nehmt ihn aus und seht nach, ob er den Ring verschluckt hat.", progress = "Ihr habt nicht zufällig meinen Ring gesehen, oder? Ich glaube, einer der Höhlenfische hat ihn verschluckt...", completion = "Ihr habt also meinen Ring gefunden, wie? Ich bin Euch überaus dankbar.\n\nUm ganz ehrlich zu sein, ich habe keine Ahnung, warum ich das Ding überhaupt behalte. Ich erinnere mich noch nicht einmal, wie er in meinen Besitz gekommen ist... vermutlich bin ich einfach ein Gewohnheitstier.\n\nWie ich schon sagte, bin ich Euch sehr dankbar. Diese Dinge hier habe ich während meiner Suche nach dem Ring gefunden. Vielleicht sind sie für Euch von Nutzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29347] = { id = 29347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendköder", description = "Wenn Ihr schon mal auf der Jagd nach Flusskrebsen wart, dann wisst Ihr, dass sie am besten auf Lebendköder reagieren. Und je mehr Köder, desto besser! Würdet Ihr gerne meinen neuen Köder ausprobieren? Schmiert Euch einfach damit ein und hüpft in den Helmsbettsee im östlichen Dun Morogh.\n\nBringt Euren Fang zu Koch Ghilm am Steinbruch Gol'Bolar westlich des Sees. Er ist ein Experte in der Zubereitung dieser zu groß geratenen Krabbeltiere!", sourceObjective = "Benutzt Grimnurs Köder an Euch selbst und springt dann in den Helmsbettsee in Dun Morogh.", completion = "Sie sind wunderschön, {name}! Grimnur wird so stolz sein, wenn er davon hört!\n\nOh, er hat mir gesagt, ich soll Euch das hier geben, wenn der Plan aufgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29348] = { id = 29348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Fische für Donnerfels", description = "Der Fischteich von Donnerfels wird von gefräßigen Azsharaschlangenköpfen heimgesucht. Es sind kaum noch Kleinfische oder Matschschnapper übrig.\n\nUnsere Angler sind schon dabei, so viele Schlangenköpfe wie möglich zu töten, aber könntet Ihr uns bei unseren Bemühungen, den Teich wieder zu bevölkern, ein wenig zur Hand gehen?\n\nWenn Ihr ein paar Fische aus dem Steinbullensee sammeln könntet und sie hierher nach Donnerfels bringt, wäre ich sehr dankbar.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 2 scharfe Kleinfische und 2 liebestolle Matschschnapper aus dem Steinbullensee in Mulgore.", progress = "Habt Ihr die Fische aus dem Steinbullensee dabei?", completion = "Wir wissen Eure Hilfe sehr zu schätzen, {name}.\n\nHoffentlich helfen diese Fische dabei, unseren Fischteich wieder zu bevölkern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29349] = { id = 29349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Flusskrebs", description = "Eine der berühmtesten Delikatessen Mulgores sind die Flusskrebse, die in unseren Seen und Flüssen leben. Sie sind besonders beliebt bei Hochzeiten oder Geburtsfeiern.\n\nWürdet Ihr mir dabei helfen, einige dieser gerissenen Krustentiere für die Kochtöpfe von Donnerfels zu fangen?\n\nIhr könnt sie im Steinbullensee angeln, oder einfach hineinspringen und sie so fangen.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 10 Steinbullenflusskrebse aus dem Steinbullensee in Mulgore.", progress = "Krebse sind so schmackhaft. Habt Ihr viele gefangen?", completion = "Ah, so viele Krebse!\n\nHabt Ihr sie geangelt? Oder seid Ihr ihnen hinterhergeschwommen?\n\nIst auch egal. Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29350] = { id = 29350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gnomische Köder-o-Matik", description = "Einer von den gnomischen Ingenieurskunstlehrern hat mir die Baupläne für einen raffinierten Köder gegeben, von dem er behauptet, dass er mir hilft, Fische schneller zu fangen und sie davon abzuhalten, abzuhauen.\n\nHier sind die Baupläne. Ihr werdet glänzende Schmuckstücke benötigen, die Ihr von meiner Assistentin im Gebäude erhalten könnt, einen haarfeinen Sprengstoffauslöser von einem Händler für Ingenieurskunstwaren in Tüftlerstadt und ein paar Rattenfallen von der Tiefenbahn.", sourceObjective = "Benutzt die Baupläne für einen Köder-o-Matik mit 5 glänzenden Schmuckstücken, einem haarfeinen Sprengstoffauslöser und 3 Rattenfallen um einen gnomischen Köder-o-Matik herzustellen.", progress = "Und, wie sieht's aus mit diesem raffinierten neuen Köder?", completion = "Ich denke, es sieht nicht nach was aus, was ein Fisch interessant finden könnte, aber man weiß ja nie. Fische sind seltsame Viecher. Danke, dass Ihr es versucht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29351] = { id = 29351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Runde für die Wachen", description = "Die Wachen, die Eisenschmiede schützen, riskieren ihr Leben im Kampf gegen unsere vielen Feinde, und es ist an uns, uns um sie zu kümmern.\n\nHeute bestehen ihre Rationen aus zwei Lieblingsdingen der Zwerge: Haggis und Silberbräu aus Eisenschmiede. Wäret Ihr so gut, mir dabei zu helfen, die Rationen zu verteilen? Dadurch bekommen alle ihr Essen rechtzeitig und wir können zu der Erledigung anderer Aufgaben übergehen.", sourceObjective = "Verteilt die Rationen aus Eisenschmiede an 6 Wachen aus Eisenschmiede.", completion = "Eine volle Wache ist eine glückliche Wache, pflege ich immer zu sagen. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29352] = { id = 29352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelmangel", description = "Oh nein, {name}, das wird ein Desaster, wenn wir nicht bald ein paar Hühner finden... Man kann doch eine Lauch-Hühnersuppe nicht ohne Huhn kochen! Das geht einfach nicht!\n\nEs ist immer noch Zeit genug, die Suppe und die Brühe herzustellen, wenn Ihr ein paar frische Hühner findet. Werdet Ihr mir helfen? Es laufen normalerweise immer ein paar Hühner außerhalb des Haupteingangs der Stadt herum. Wenn Ihr, sagen wir mal, sechs von ihnen erwischt, dann würdet Ihr mir den Hals retten.", sourceObjective = "Fangt 6 Hühner von Dun Morogh in der Nähe des Eingangs von Eisenschmiede.", progress = "Die Hühner, {name}, habt Ihr sie oder nicht?", completion = "Ja, das ist genau das, was ich brauchte. Ihr habt meinen Dank, {name}, und meine Entschuldigung, dass ich vorher so barsch war. Ich kann den Gedanken einfach nicht ertragen, dass eine Mahlzeit nicht rechtzeitig fertig wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29353] = { id = 29353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haggis für alle!", description = "Der Haggis muss fließen. Na gut, bildlich gesprochen. Haggis wird niemals flüssig sein! Ihr wollt gar nicht wissen, was passiert, wenn die Bevölkerung von Eisenschmiede keinen Haggis bekommt.\n\nIch arbeite gerade an der nächsten Ladung, aber mir fehlen noch ein paar Zutaten.\n\nSognar Klippenbart ist der Fleischverkäufer im Militärviertel und er kann Euch den Sack voller Schafsinnereien verkaufen, den ich brauche. Milde Gewürze bekommt Ihr von jedem Kochbedarfshändler und Säcke voller Hafermehl findet Ihr in den Gasthäusern oder den Vorratslagern der Stadt.", sourceObjective = "Besorgt einen Sack voller Schafsinnereien, 5 Pakete milder Gewürze und 4 Säcke voller Hafermehl.", progress = "Habt Ihr die Zutaten?", completion = "Ihr habt sie alle? Wunderbar! Dann frisch ans Werk.", sourceObjectiveStatus = "unverified-source-field" }
quests[29354] = { id = 29354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzende Schmuckstücke", description = "Eines der einfachsten und nützlichsten Hilfmittel eines jeden Anglers ist das glänzende Schmuckstück. Selbst der ungeübteste Angler hat mit einem glänzenden Schmuckstück an der Sehne gute Chancen.\n\nBei all dem Fischen in letzter Zeit gehen die Vorräte von Donnerfels aber schnell zur Neige!\n\nKönnte ich Euch bitten, glänzende Steine vom Fuß der zentralen Anhöhe zu sammeln? Bringt sie zu Nahari Wolkenjäger, damit sie mit ihnen Nachschub anfertigen kann.", sourceObjective = "Nahari Wolkenjäger in Donnerfels braucht 20 glänzende Steine vom Fuß der zentralen Anhöhe.", progress = "Habt Ihr mir vielleicht ein paar glänzende Steine mitgebracht?", completion = "Das sind aber besonders hübsche Steine! Daraus werden perfekte glänzende Schmuckstücke werden, danke sehr.\n\nHier... Kah hat mir Bescheid gesagt, dass Ihr mit den Steinen vorbeikommen würdet und hat mich gebeten, Euch dies bei Eurer Ankunft zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29355] = { id = 29355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrot en masse", description = "Es mag zwar nichts Besonderes sein, {name}, aber Gewürzbrot ist in Eisenschmiede schon seit jeher sehr beliebt. Manchmal komme ich mit meinen Lieferungen gar nicht hinterher!\n\nMöchtet Ihr vielleicht ein paar Laibe backen, damit Ihr nicht aus der Übung kommt, und mir damit helfen, meine Kunden zu versorgen? Ihr könnt alle Zutaten, die Ihr braucht, von meinem Bruder, Emrul Riknussun, ein Stockwerk unter uns erhalten.", sourceObjective = "Backt oder erhaltet 10 Scheiben Gewürzbrot.", progress = "Wie läuft es mit dem Gewürzbrot?", completion = "Dieses Brot sieht köstlich aus. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29356] = { id = 29356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Bierdürftigen", description = "Mein Vorrat an EKW, Eisenschmieder Kristallweizen für Euch Grünschnäbel, gehen zur Neige. Zum Glück ist die Brauerei nicht weit weg und die sollten schon ein neues Fass voll Drugans EKW für uns haben. Dieser Drugan ist ein echtes Brauereigenie, sag' ich Euch.\n\nIch werde es heute nicht schaffen, selbst nach Kharanos hinunterzulaufen, aber vielleicht könnt Ihr dort hinunter flitzen, ein neues Fass abholen und es hierher bringen? Was sagt Ihr?", sourceObjective = "Holt das Fass voll Drugans EKW von der Brauerei in Kharanos ab und bringt es nach Eisenschmiede zurück.", progress = "Und? Habt Ihr das Fass oder nicht?", completion = "Ah, gut gemacht! Ich sage Euch, dieser Drugan ist ein echtes Universalgenie - Entdecker, Historiker, Brauer - gibt es etwas, das dieser {race} nicht gemeistert hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[29357] = { id = 29357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Gewürzbrot", description = "Ist es nicht erstaunlich, wie etwas so einfaches wie Gewürzbrot jeden Tag in Darnassus verbraucht wird? Wenn ich mich nicht um meine anderen Verantwortlichkeiten kümmere, dann backe ich gerne Gewürzbrot, um meine Fähigkeiten als Koch zu verfeinern und an meiner Technik zu arbeiten.\n\nWarum probiert Ihr es nicht mal aus? Ihr solltet die Zutaten eigentlich hier im Laden finden.\n\nEgal wie viel wir herstellen, es wird nie schlecht. Bringt mir einige Laibe, wenn Ihr fertig seid und ich werde jemanden schicken, um sie mit unseren Freunden, den Gilneern, zu teilen.", sourceObjective = "Stellt 10 Laibe Gewürzbrot her oder besorgt sie Euch anderweitig.", progress = "Ich liebe diesen Geruch von frisch gebackenem Brot einfach, besonders von Gewürzbrot, Ihr nicht?", completion = "Diese hier sind gut gemacht, {name}. Ich hoffe, Ihr fandet es genauso entspannend wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29358] = { id = 29358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir benötigen mehr Pinienkerne", description = "Die Shu'halo verwenden Pinienkerne in so vielen Gerichten: Wild, Fisch, Gemüse, selbst Backwaren versetzen wir mit ihnen.\n\nDie Erdenmutter hat uns damit gesegnet, dass die allerbesten Pinienkerne von den Bäumen auf diesen Anhöhen stammen.\n\nSammelt einfach Kienäpfel und röstet sie über einem Feuer, damit die Kerne herausfallen. Es sind fast nie genug für alle da...", sourceObjective = "Sammelt 30 Pinienkerne, indem Ihr Kienäpfel von Mulgore in Donnerfels sammelt und sie röstet. Liefert die Kerne bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr viele dieser leckeren Pinienkerne finden können?", completion = "Ihr arbeitet so schnell!\n\nIch sorge dafür, dass sie an die verschiedenen Köche und Bäcker von Donnerfels verteilt werden.\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[29359] = { id = 29359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klassiker", description = "Hering ist eine der meistverlangten Fischarten in Darnassus, aber Hering ist nicht gleich Hering. Der Kaldoreihering kommt nur in den Gewässern um Teldrassil vor.\n\nIch versuche, immer ein paar vorrätig zu haben, weil dieser Fisch so vielseitig ist! Ich habe gerade erst wieder welche fertig geräuchert, deshalb muss ich meine Vorräte aufstocken. Würde es Euch etwas ausmachen, mir zu helfen? Ihr könnt Kaldoreihering fangen, wenn Ihr in der Nähe von Rut'theran angelt.", sourceObjective = "Angelt 8 Kaldoreiheringe, indem Ihr in der Nähe von Rut'theran Eure Angel auswerft.", progress = "Habt Ihr die Heringe?", completion = "Danke! Ich frage mich, was ich mit denen wohl anstellen könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[29360] = { id = 29360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und als Beilage: Fliegen", description = "Wir verpflegen hier nicht nur die Orcs, {class}. Diesmal geht es darum, Nahrung für deren Ablösung zuzubereiten.\n\nWir müssen klein beginnen und Fliegen fangen. Fliegen lieben fauliges Fleisch und wir lieben fauliges Fleisch... als Belagerungsgeschosse!\n\nDurchsucht die Fleischwagen nach überschüssigen Fleischbrocken. Wo es Fleisch gibt, gibt es auch Fliegen.\n\nBringt mir 25 fette Fliegen, damit ich Phase zwei unseres Kochplans einleiten kann.", sourceObjective = "Beschafft 25 fette Fliegen von dem \"Fleisch\" in der Nähe der Fleischwagen. Kehrt anschließend zu Eunice Burch in Unterstadt zurück.", progress = "Ich wette, ein Bisschen von dem \"Fleisch\" ist noch gut.", completion = "Ah! Perfekt! Fett, träge und bereit, gefressen zu werden! Als nächstes werden wir sie an unsere Spinnen verfüttern. Die werden gemästet und dann verfüttern wir sie an die Frösche...\n\nAch, ich plappere schon wieder. Die Details müsst Ihr gar nicht wissen. Das ist nur ein kleiner Schritt in einem großen kulinarischen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29361] = { id = 29361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Monster im Burggraben", description = "Manchmal muss man beim Angeln seinen Fang wieder ins Wasser zurückwerfen, {class}.\n\nWir haben diese Frösche nur für diesen Zweck gemästet. Sie haben fette Spinnen bekommen, die ihrerseits mit fetten Fliegen gefüttert worden sind, und jetzt füttern wir ein echtes Monster.\n\nIn den Burggräben an der Oberfläche, in den Ruinen von Lordaeron, lebt unser eigenes Burggrabenmonster.\n\nHeute ist Fütterungstag. Aber wir müssen es dabei auch abrichten. In diesem Beutel findet Ihr einen Lockvogelbausatz und ein paar fette Frösche. Stellt den Lockvogel auf und werft dem Monster die Frösche zu, sobald es auftaucht.", sourceObjective = "Benutzt den Allianzlockvogelbausatz, um das Burggrabenmonster in den Ruinen von Lordaeron hervorzulocken. Verwendet dann die fetten Frösche, um das Monster zu füttern.", completion = "Die Toten ernähren die Fliegen. Die Fliegen ernähren die Spinnen. Die Spinnen ernähren die Frösche. Die Frösche füttern unser Burggrabenmonster... ein entzückender Lebenszyklus, bei dem so viele Leben beendet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29362] = { id = 29362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Magische\" Pilze", description = "Ihr kennt doch sicher die Teiche der Visionen, oder?\n\nDort wächst eine bestimmte Pilzart... nicht die ledrigen, wuchernden Pilze, die dort überall stehen, sondern kleinere, zerbrechlichere Schwämme, die unter ihnen wachsen.\n\nSie sind selten, sehr köstlich und verleihen Gerichten einen Geschmack, den man magisch nennen könnte.\n\n...Was denn? Ernsthaft. Sie schmecken einfach nur gut. Sonst nichts.", sourceObjective = "Sammelt 6 \"magische\" Pilze aus den Teichen der Visionen in Donnerfels. Liefert sie bei Aska Nebelläufer in Donnerfels ab.", progress = "Konntet Ihr die Pilze finden?", completion = "Danke, {name}! Ich bin sicher, dass sie ein einfach magisches Aroma in jedes Gericht zaubern.\n\nWas ist denn? Hört auf mich so anzuschauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29363] = { id = 29363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrot aus Mulgore", description = "Ich werde oft gefragt \"Aska, wer bäckt eigentlich all dieses Gewürzbrot aus Mulgore?!\"\n\nEine berechtigte Frage. Unser gutes und edles Brot wird an unzähligen Orten in jedem Winkel Azeroths gehandelt, selbst von unseren erbittertsten Feinden. SO LECKER IST ES!\n\nUnd die Antwort lautet...?\n\n\"IHR seid es.\" Bitte nehmt dieses Packet mit Gewürzen aus Mulgore und macht damit aus fadem, langweiligem Gewürzbrot Gewürzbrot aus MULGORE!", sourceObjective = "Kombiniert die Gewürze aus Mulgore mit Gewürzbrot, um 5 Laibe frisches Gewürzbrot aus Mulgore herzustellen (Ihr könnt Euer eigenes Gewürzbrot backen, oder welches aus anderen Quellen verwenden). Liefert die Brote bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr schon das Gewürzbrot aus Mulgore gebacken?", completion = "Ooh, das Brot duftet aber köstlich. Ihr seid ja ein Meisterbäcker.\n\nWer weiß, wie weit diese exquisiten Laibe reisen werden... wie ich höre, sind sie sogar bei den Draenei auf der Azurmythosinsel beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29364] = { id = 29364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisbrei", description = "Eins der wichtigsten Grundnahrungsmittel hier in Donnerfels ist Maismehl; in fast jedem Haushalt findet man Schüsseln mit Mais.\n\nDa so viele Mühlen im Land ständig von Harpyien, Gnollen, rücksichtslosen Bergbaugesellschaften und Erdenmutter weiß von wem angegriffen werden, bitte ich oft meine Lehrlinge, beim Maismahlen mitzuhelfen.\n\nWürdet Ihr vielleicht auch mit anfassen?", sourceObjective = "Helft den Bewohnern von Donnerfels, Maismehl herzustellen, indem Ihr Schüsseln mit Maiskörnern mahlt.", completion = "Es steckt viel Arbeit darin, genügend Maismehl für alle zu machen. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29365] = { id = 29365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekt ausgewählte Portionen", description = "Selbst Einsteigerköche wissen, dass ein großartiges Gericht mit großartigen Zutaten beginnt.\n\nIch habe bei den Händlern von Donnerfels Daueraufträge, aber ich möchte gern sehen, wie ihr Euch dabei schlagt, die allerbesten Waren auszuwählen, die sie im Angebot haben.\n\nBitte geht von Händler zu Händler und besorgt mir perfekte Portionen Fleisch, Fisch, Gemüse und Kräuter.", sourceObjective = "Besorgt vier \"perfekte Portionen\" von den Händlern in Donnerfels. Liefert die Zutaten bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr alle nötigen Zutaten gesammelt?", completion = "<Aska beäugt die Zutaten, die Ihr ausgewählt habt.>\n\nMmmhmmm. Ja. Gut gemacht!\n\nIch hätte sie selbst nicht besser auswählen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29371] = { id = 29371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Verlierens", description = "Seid gegrüßt, {class}. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Horde versucht, unsere Feierlichkeiten zu ruinieren.\n\nDie schlauste Lösung wäre es wohl, einfach darüber zu stehen und diese Angriffe zu ignorieren.\n\nIch bewundere diejenigen, die das schaffen, doch ich kann ihnen nicht helfen. Doch denjenigen, die zurückschlagen möchten... denen kann ich helfen. Falls Ihr Interesse habt, {class}, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Horde in den Ruinen von Lordaeron ein.", sourceObjective = "Benutzt das Löschmittel gegen den Weidenmann in den Ruinen von Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[29372] = { id = 29372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Posemuckel", description = "Gesetzlose haben den Sheriff entführt!", sourceObjective = "Rettet den Sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29373] = { id = 29373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Posemuckel", description = "Wir haben Sheriff Blundy niemals besonders viel Aufmerksamkeit geschenkt, wie er sich da ständig aufgeplustert hat wegen seinen \"Gesetzen\" und \"Fehl-ver-halt-en\". Aber den dreckigen alten McClintocks und ihrem Kuhtreiber von einem Vater vom Truckshawgrat hat es bis hier gestanden mit den ständigen Kerkerhaften und Verhandlungen und Sippenhaften und \"Tot oder lebendig!\"-Steckbriefen und da sind sie letzte Woche gekommen und haben das Gesetz in die eigenen Hände genommen - im wahrsten Sinne des Wortes - indem sie den guten Sheriff verschleppt haben.", sourceObjective = "Rettet den Sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29374] = { id = 29374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkbomben los!", description = "Die närrische Allianz hat Hexen eingestellt, um einen Angriff auf unsere Stadt durchzuführen. Na, wie meine Schwester mal gesagt hat: \"Gleiches Recht für alle!\".\n\nWir werden ihnen den Gefallen mit Freuden zurückzahlen. Sprecht mit meiner Schwester und sie wird Euch einen Ritt auf einem Besen über Sturmwind organisieren. Sobald Ihr Euch über Sturmwind befindet, solltet Ihr die Stinkbomben auf die Stadt und ihre Einwohner fallen lassen. Lasst sie leiden!\n\nWir werden diesen Hexen in Sturmwind schon zeigen, wer mächtiger ist.", sourceObjective = "Sprecht mit Crina Fenlow und nehmt einen Besen, um damit über Sturmwind zu fliegen. Benutzt die Stinkbomben, um die Stadt und ihre Einwohner damit zu bewerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29375] = { id = 29375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen in Unterstadt", description = "Seid gegrüßt, {class}! Genießt Ihr die Schlotternächte? Es scheint, dass die Allianz als Antwort auf unseren Stinkbombenangriff auf Sturmwind auch unsere Stadt mit Stinkbomben angreift.\n\nZum Glück verfügen wir über Magien, die mit dem Gestank der Allianz fertig werden. Benutzt diesen Arkanreiniger, um die Stinkbomben aus der Stadt zu beseitigen.", sourceObjective = "Benutzt den Arkanreiniger, um die Stinkbomben in Unterstadt zu entfernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29376] = { id = 29376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Aufbaus", description = "Wir verbrennen den Weidenmann als Symbol für unseren Kampf gegen diejenigen, die sich uns in den Weg stellen. Wir tragen die Asche des verbrannten Weidenmanns als Symbol für den niemals endenden Kampf gegen diejenigen, die uns versklaven wollen.\n\nBenutzt das nahe Lagerfeuer, um den Weidenmann zu entzünden. Nehmt Euch dann die herumliegende Asche und beschmiert Euer Gesicht damit.\n\nDiese Gesten werden unsere Feinde daran erinnern, dass wir niemals innehalten werden.", sourceObjective = "Benutzt das Freudenfeuer vor dem Weidenmann, um ihn in Brand zu stecken. Benutzt die Asche auf dem Boden in der Nähe des Weidenmanns.", sourceObjectiveStatus = "unverified-source-field" }
quests[29377] = { id = 29377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Vandalismus", description = "Seid gegrüßt, {class}. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Allianz versucht, unsere Feierlichkeiten zu ruinieren.\n\nWir haben die Möglichkeit, es ihnen heimzuzahlen. Falls Ihr Interesse habt, {class}, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Allianz vor Sturmwind ein.\n\nLöscht ihre Flamme und erfreut Euch an ihrem Leid.", sourceObjective = "Benutzt das Löschmittel gegen den Weidenmann vor Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29385] = { id = 29385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[29386] = { id = 29386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Hyjal!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29387] = { id = 29387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Helden der Allianz sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29388] = { id = 29388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Champions der Horde sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29389] = { id = 29389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Eure Arbeit hat uns den Vorteil verschafft, den wir brauchen, um gegen die Bewohner der Feuerlande zu mobilisieren. Genau in diesem Moment versammeln wir unsere Invasionsstreitkräfte südlich Eurer Position.\n\nWir könnten Eure Stärke ein weiteres Mal brauchen, {race}. Sprecht mit Matookla am Heiligtum von Malorne. Sie koordiniert die Invasionsanstrengungen.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29390] = { id = 29390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Der Ruf der Uralten", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Lo'Gosh, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Befehl des Kriegshäuptlings auf einem beliebigen Aufrufbrett der Horde umsehen.", sourceObjective = "Helft Lo'Gosh, Tortolla, Aviana und Aessina beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29391] = { id = 29391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Der Ruf der Uralten", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Goldrinn, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Heldenaufruf auf einem beliebigen Aufrufbrett der Allianz umsehen.", sourceObjective = "Helft Goldrinn, Tortolla, Aviana und Aessina beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29392] = { id = 29392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Erbstücke", description = "Meine letzten Besitztümer hätten eigentlich heute aus Theramore eintreffen sollen. Das Schiff ist angekommen, aber ich habe nichts von dem Kurier gehört. Die Kiste, die er transportieren sollte, enthält Gegenstände, die schon seit Generationen im Familienbesitz sind.\n\nWürdet Ihr vielleicht hinunter zum Hafen von Sturmwind gehen und nachsehen, was ihn aufhält?", sourceObjective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers im Hafen von Sturmwind nach Hinweisen, was den Kurier aufhalten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29396] = { id = 29396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Souvenirlieferant", description = "<seufz>\n\nHört mir auf mit den Krügen vom letzten Jahr...\n\nIch glaube, dass diese zwielichtigen Bierkruglieferanten irgendwas mit diesem merkwürdigen Schattenhammerkult zu tun hatten, der aufgetaucht ist, bevor die Elementare eingefallen sind.\n\nUnd das ist der Grund, warum wir einen neuen Lieferanten und einen besseren Krug haben!\n\nHier habt Ihr einen Gutschein für einen Bierkrug.\n\nSprecht mit Blix in der Nähe des hinteren Endes des Braufestlagers. Er ist ziemlich seltsam, vor allem, weil er immer diese Brille aufhat. Er wird den Gutschein für Euch bearbeiten, und alle anderen Transaktionen des Braufests.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29398] = { id = 29398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hehlerware", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?", sourceObjective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29399] = { id = 29399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise vergleichen", description = "Ich habe dem 'Herrn' gesagt, dass es da einen Laden im Zwergendistrikt gibt, der vielleicht besser geeignet ist für seine Bedürfnisse. Er heißt \"Schattenspiele\" und Ihr findet den Eingang in der Nähe der Kanäle auf der westlichen Seite des Distrikts.\n\nQuincy Messerschmied ist Euer Mann. Er handelt mit Waren, die ein ehrlicher Händler nicht mal mit der Kneifzange anfassen würde!", sourceObjective = "Begebt Euch zum Laden \"Schattenspiele\" im Zwergendistrikt von Sturmwind und sucht nach Hinweisen auf den Besuch des Kistendiebes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29400] = { id = 29400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit zum Feiern", description = "Frohe Grüße, {class}.\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. Das Verbrennen des Weidenmanns im Besonderen ist ein Rätsel für viele außerhalb der Verlassenen.\n\nBegebt Euch zu den Ruinen von Lordaeron über Unterstadt und sprecht mit der Ruferin der Dunkelheit Yanka. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.", sourceObjective = "Sprecht mit der Ruferin der Dunkelheit Yanka in den Ruinen von Lordaeron direkt außerhalb des Eingangs zu Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29401] = { id = 29401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeweht", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Orgrimmar verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", sourceObjective = "Jaga möchte, dass Ihr 5 entflohene Ballons in Orgrimmar einsammelt.", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29402] = { id = 29402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtsmaßnahmen", description = "Ich wäre vorsichtig mit allen, die sich als rechtmäßige Besitzer der Kiste und ihres Inhalts ausgeben. Hat man Euch nicht vor der Gefahr gewarnt?\n\nHier ist eine bessere Idee: Lasst uns zusammenarbeiten, um die Kiste zurückzuholen und sicherzugehen, dass ihr Inhalt niemandem schadet. Um uns selbst zu schützen werden wir ein Gebräu benötigen, das aus einigen Ingredienzien besteht, die in der Stadt zu finden sind.\n\nKauft etwas arkanes Pulver bei einem Reagenzienhändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln in den Feldern nördlich der Stadt.", sourceObjective = "Besorgt Euch 5 Kristallphiolen, 5 Portionen arkanes Pulver und 5 Blutnesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29403] = { id = 29403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Agent des Sammlers", description = "Quincy zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in den Katakomben unterhalb der Kathedrale des Lichts treffen.\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Goldenen Fass\", sobald Ihr die Kiste habt.", sourceObjective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Katakomben unterhalb der Kathedrale des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29411] = { id = 29411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was jetzt?", description = "Endlich habt Ihr die Kiste gefunden, die Anson Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Archäologielehrlings korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Hudson Barnes geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?", sourceObjective = "Gebt die Kiste Anson Hastings in der \"Güldenen Rose\" in Sturmwind.\n\n-ODER-\n\nGebt die Kiste Hudson Barnes im \"Goldenen Fass\" in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29412] = { id = 29412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeweht", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Sturmwind verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", sourceObjective = "Vin möchte, dass Ihr 5 entflohene Ballons in Sturmwind einsammelt.", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29413] = { id = 29413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unheimliche Kiste", description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch." }
quests[29415] = { id = 29415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Erbstücke", description = "Ich habe dem Kurier gesagt, dass er den Zeppelin nehmen soll, aber nein, er musste ja unbedingt ein Goblinschiff nehmen! Na ja, jetzt ist er verspätet und die wertvollen Erbstücke meiner Familie sind bei ihm.\n\nWenn Ihr helfen wollt, könntet Ihr vielleicht hinunter zu den Docks östlich von Orgrimmar gehen, Euch an Bord des Goblinschiffs begeben und nachsehen, was ihn aufhält?", sourceObjective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers in den Docks östlich von Orgrimmar nach Hinweisen, was den Kurier aufhalten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29426] = { id = 29426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtsmaßnahmen", description = "Es hat Euch also jemand anders angeheuert, um diese Kiste zu besorgen? Das hört sich für mich gar nicht gut an.\n\nDer Inhalt dieser Kiste gehört unter die Aufsicht der Archäologischen Akademie. Die in ihr enthaltenen Gegenstände sind sehr mächtig und sehr gefährlich.\n\nWir müssen zu dem Treffen gehen, dass Dran zwischen dem Dieb und dem Sammler vereinbart hat, aber zunächst müssen wir uns vor den Effekten schützen, die der Umgang mit der Kiste mit sich bringt.\n\nKauft etwas arkanes Pulver bei einem Reagenzienhändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln im Tal der Weisheit.", sourceObjective = "Besorgt Euch 5 Kristallphiolen, 5 Portionen arkanes Pulver und 5 Blutnesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29429] = { id = 29429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unheimliche Kiste", description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch." }
quests[29430] = { id = 29430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Wisst Ihr, ich habe Anson noch gar nicht hier draußen gesehen.\n\nIn letzter Zeit verbringt er seine ganze Zeit damit, sich in der \"Güldenen Rose\" volllaufen zu lassen.\n\nEtwas muss ihm wirklich an die Nieren gehen! Würdet Ihr vielleicht mal nach ihm sehen?", sourceObjective = "Besucht Anson Hastings in der \"Güldenen Rose\" in Sturmwinds Handelsdistrikt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29431] = { id = 29431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Mit meinem Freund Edgar ist etwas nicht in Ordnung. Normalerweise liebt er die Festivitäten rund um die Schlotternächte.\n\nEr verbringt seine ganze Zeit damit, in der Kneipe \"Zum Gebrochenen Hauer\" in Orgrimmar mit den Orcs zu trinken. Wäret Ihr so gut und würdet mal bei ihm vorbeischauen und nachsehen, ob es irgendwas gibt, womit man ihn aufmuntern könnte?", sourceObjective = "Sprecht mit Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29433] = { id = 29433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Eure Stärke", description = "Einige Leute haben so lange Spaß, bis jemand verletzt wird. Ich nenne solche Leute Schwächlinge.\n\nWahre Stärke beweist nur der, der jemanden oder etwas verletzt. Ihr verletzt Euch selbst, weil Ihr Euren Körper an seine Grenzen führt, und Ihr verletzt die, die anderen schaden wollen.\n\nWenn Ihr der Stärkste sein wollt, müsst Ihr kämpfen. Wie wichtig ist Euch das?\n\nIch will, dass Ihr die niederstreckt, die Euch herausfordern und mir einen Beweis Eures Triumphs bringt.", sourceObjective = "Kerri Hicks möchte, dass Ihr 250 grausige Trophäen erbeutet. Um sie zu bekommen, müsst Ihr Wesen töten, die Euch Erfahrung oder Ehre gewähren und den Abenteuerführer des Dunkelmond-Jahrmarkts bei Euch tragen.", progress = "Ohne Fleiß kein Preis.", completion = "Habt Ihr Euch Herausforderungen gesucht oder einfach nur Eber auf einem Feld abgeschlachtet?\n\nIch bin aus gutem Grund die Stärkste.\n\nVielleicht werde ich Euch eines Tages zeigen, wie stark ich wirklich bin, {class}. Bis dahin müsst Ihr Euch weiter anstrengen, aber vergesst nicht, ab und zu eine Pause zu machen.\n\nSo wie jetzt zum Beispiel. Hier, genießt den Dunkelmond-Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29434] = { id = 29434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzergeneral", description = "Willkommen zu unserem bescheidenen kleinen Dampfpanzerkampf-Simulator! Für nur einen Spieljeton könnt Ihr Euer strategisches Können unter Beweis stellen. Fahrt über unseren Parcours und zerstört die Panzerziele.", sourceObjective = "Zerstört mit Eurem Dunkelmond-Panzer 30 Ziele in der veranschlagten Zeit.", progress = "Aufgetankt und einsatzbereit!", completion = "Eine beeindruckende Demonstration!\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29436] = { id = 29436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die menschliche Kanonenkugel", description = "Für nur einen Spieljeton des Dunkelmond-Jahrmarkts könnt Ihr Euch aus der Blastenheimer 5000 Ultrakanone abschießen lassen. Doch damit ist der Spaß noch nicht vorbei! Wir haben ein Ziel im Meer nahe des Piers aufgebaut.\n\nWenn Ihr bei Euren Landungen fünf Punkte erzielt, könnt Ihr Gewinnlose bekommen.\n\nEin Treffer ins Schwarze bringt 5 Punkte, einer ins Ziel 3 Punkte und einer knapp neben dem Ziel 1 Punkt.\n\nViel Glück bei der Landung!", sourceObjective = "Erreicht 5 Kanonenzielpunkte, indem Ihr in der Nähe des Kanonenziels landet.", progress = "Hals und Beinbruch!", completion = "5 Punkte? Gut gemacht! Hier sind Eure Lose.\n\nViel Spaß auf dem Rest des Dunkelmond-Jahrmarkts!", sourceObjectiveStatus = "unverified-source-field" }
quests[29437] = { id = 29437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Wächter", description = "Fandral Hirschhaupt ist hier auf dem Hyjal gefangengehalten worden. Es war der grüne Drache Alysra - eine von uns! -, die damit beauftragt war, Fandral zu bewachen.\n\nWir können nur vermuten, dass es dem Schattenhammer gelungen ist, sie zu verderben. Ihr müsst sie stellen, {name}. Vernichtet sie, wenn es sein muss - ich kann es nicht ertragen, dabei zuzusehen.\n\nZuletzt wurde sie bei den Ruinen von Lar'donir gesichtet, westlich des Weltenbaums.", sourceObjective = "Stellt und tötet Alysra bei den Ruinen von Lar'donir.", sourceObjectiveStatus = "unverified-source-field" }
quests[29438] = { id = 29438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er schießt, er trifft!", description = "Glaubt Ihr, dass Ihr gut schießen könnt? Habt Ihr eine ruhige Hand?\n\nWie wäre es dann mit ein paar Schüssen?\n\nEs kostet Euch nur einen Spieljeton, Eure Fähigkeiten unter Beweis zu stellen.\n\nNa, wie gut seid Ihr?", sourceObjective = "Erreicht 25 Punkte in 60 Sekunden.", progress = "Ein stehendes Ziel zu treffen, ist nicht so einfach, wie es aussieht.", completion = "Ich wusste, dass Ihr das schafft, {class}. Hier ist Euer Preis. Genießt den Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29439] = { id = 29439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Weltenschamanen", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, {name}.\n\nAls ein Mitglied der Allianz weiß ich, dass Ihr möglicherweise Bedenken hegt, mit dem, den Ihr Thrall nennt, dem früheren Kriegshäuptling der Horde, zusammenzuarbeiten. Aber er hat explizit darum gebeten, dass es ein Held der Allianz ist, der ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nLasst Eure Zweifel beiseite, {class}, und antwortet dem Ruf des Weltenschamanen.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", sourceObjective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29440] = { id = 29440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Weltenschamanen", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, {name}.\n\nThrall hat sein Amt als Kriegshäuptling der Horde niedergelegt, aber für seine neue Aufgabe benötigt er die Unterstützung seines Volkes mehr als je zuvor. Er hat darum gebeten, dass einer der besten Streiter der Horde ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", sourceObjective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29441] = { id = 29441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Bauch der Bestie" }
quests[29443] = { id = 29443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger Kristall", description = "Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.\n\nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.", sourceObjective = "Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr den her?\n\nSolche Kristalle sind sehr selten, viele Sammler suchen danach. Ich würde diesen gern untersuchen und auf dem Jahrmarkt ausstellen. Würdet Ihr ihn gegen eine großzügige Anzahl von Losen des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29444] = { id = 29444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein exotisches Ei", description = "Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.\n\nBringt das Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt.", sourceObjective = "Bringt das monströse Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr dieses Ei gefunden? Darin verbirgt sich sicherlich etwas Monströses und Wunderbares. Ein sehr passender Neuzugang für unseren Zoo. Würdet Ihr Euch davon für eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts trennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29445] = { id = 29445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Zauberfoliant", description = "Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten gnollischen Jahrmarktswahrsager auf dem Dunkelmond-Jahrmarkt, von Interesse sein.", sourceObjective = "Bringt den geheimnisvollen Zauberfolianten zu Sayge auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Ein seltsamer Zauberfoliant, wie interessant! So einen habe ich noch nie gesehen. Ich hätte ihn sehr gern für meine Sammlung. Würdet Ihr ihn gegen Lose des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29446] = { id = 29446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wundersame Waffe", description = "Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Einige winzige Scharten weisen darauf hin, dass sie auch im Kampf benutzt wurde.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt, daher würde sich Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt bestimmt für dieses Stück interessieren.", sourceObjective = "Bringt die verzierte Waffe zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr eine solch wundervolle Klinge gefunden?\n\nWas für eine Verarbeitung! Das ist wahrlich eine Waffe, mit der sich jeder Held schmücken könnte. Ich würde sie sehr gern ausstellen.\n\nWürdet Ihr eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29451] = { id = 29451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterstratege", description = "Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren.", sourceObjective = "Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Das sieht nach einem sehr seltenen Buch aus…", completion = "Ich weiß nicht, wie Ihr daran gekommen seid und ich bin klug genug, nicht zu fragen. Würdet Ihr Euch für Lose des Dunkelmond-Jahrmarkts davon trennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29455] = { id = 29455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft den Ring", description = "Hey Ihr! Haltet ein!\n\nWollt Ihr allen beweisen, wie talentiert Ihr seid? Sorgt dafür, dass drei Ringe auf der Dunkelmond-Schildkröte landen, dann bekommt Ihr eine Belohnung.\n\nFür einen Spieljeton könnt Ihr einen Stapel Ringe kaufen, um der Welt zu zeigen, warum wir Euch auf dem Jahrmarkt {name}, \"<den Adleräugigen/die Adleräugige>\" nennen.", sourceObjective = "Werft 3 Ringe auf die Dunkelmond-Schildkröte.", progress = "Geht's dem Wurfarm gut?", completion = "Ich wusste, dass Ihr das könnt, {class}. Gebt uns die restlichen Ringe, falls welche übrig sind, dann bekommt Ihr Euer Gewinnlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[29456] = { id = 29456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erbeutetes Banner", description = "Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert. Zeigt ihm das Banner, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Was für ein wundervolles Banner! Das hätte ich gerne in meiner Sammlung.\n\nWürdet Ihr es mir für einige Lose des Dunkelmond-Jahrmarkts überlassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29457] = { id = 29457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Insigne des Feindes", description = "Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.\n\nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt. Zeigt ihm das Abzeichen, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal aufsucht.", sourceObjective = "Bringt das eroberte Insigne zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Das ist ein bemerkenswert gut erhaltenes Offiziersinsigne der Allianz. Viele Offiziere besuchen zwar den Jahrmarkt, aber keiner von ihnen will sich von seinen Abzeichen trennen. Würdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29458] = { id = 29458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erbeutete Tagebuch", description = "Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers handelt, der sehr von sich und seinen Abenteuern eingenommen ist.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.", sourceObjective = "Bringt das Tagebuch eines Abenteurers zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Ein bemerkenswerter Fund!\n\n<Der Professor blättert in dem Buch.>\n\nEinige Seiten sind kaum noch lesbar, aber wenn auch nur ein Drittel des Inhalts der Wahrheit entspricht, handelt es sich um einen wahren Schatz. Würdet Ihr es gegen eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29463] = { id = 29463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hau-den-Gnoll", description = "Wollt Ihr ein paar Gnolle hauen? Dann seid Ihr am richtigen Ort.\n\nEure Aufgabe ist einfach: Erreicht 30 Punkte in einer Minute.\n\nBenutzt den Holzhammer, den ich Euch geben werde und legt los. Sprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Erreicht 30 Punkte beim Gnollhauen.", progress = "Wie habt Ihr Euch geschlagen?", completion = "Ihr habt die Gnolle also besiegt. Fühlte sich gut an, oder?\n\nHier ist Euer Preis. Genießt den Rest des Dunkelmond-Jahrmarkts!", sourceObjectiveStatus = "unverified-source-field" }
quests[29464] = { id = 29464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge der Weissagung", description = "Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.\n\nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmondinsel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr diese Runensammlung her? So eine habe ich seit Jahren nicht mehr gesehen. Es wird mir eine Freude sein, ihr Rätsel zu entschlüsseln!\n\nWürdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29469] = { id = 29469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", sourceObjective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29475] = { id = 29475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kenne die Geheimnisse der Gobliningenieurskunst.\n\nIhr seht aus, als würdet Ihr gern Dinge in die Luft jagen, aber ich benötige Proben Eurer Arbeit. Bringt mir zwanzig große Eisenbomben, zwanzig Stangen robustes Dynamit und fünf explodierende Schafe.\n\nWenn Ihr diese Gegenstände zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt bringt, wird er Euch offiziell zum Gobliningenieur mit Zugang zu allen Bauplänen ernennen!", sourceObjective = "Bringt 20 große Eisenbomben, 20 Stangen robustes Dynamit und 5 explodierende Schafe zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", progress = "Überlasst mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung, dann werde ich Euch das Wissen vermitteln, das Ihr benötigt, um Mitglied im exklusiven Club der Gobliningenieure zu werden.", completion = "Anscheinend seid Ihr tatsächlich bereit für eine richtige Ausbildung. Hiermit ernenne ich Euch zum Gobliningenieur, {name}!\n\nIhr könnt Euch die teuflischen Erfindungen aller Gobliningenieure ansehen. Genießt es und versucht, Euch nicht in die Luft zu sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29477] = { id = 29477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kann Euch die Gnomeningenieurskunst beibringen.\n\nIhr scheint zwar zu wissen, was Ihr tut, aber ich benötige einige Proben Eurer Arbeit. Bringt mir sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.\n\nSobald Ihr diese Gegenstände bei einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt abgebt, seid Ihr offiziell ein Gnomeningenieur und erhaltet Zugriff auf alle Baupläne!", sourceObjective = "Bringt 6 Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", progress = "Sobald Ihr mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung unterbreitet habt, könnt Ihr ein zertifizierter Gnomeningenieur werden. Dann erhaltet Ihr uneingeschränkten Zugriff auf alle Baupläne der Gnomeningenieure.", completion = "Am heutigen Tag wird aus Euch ein echter Ingenieur, {name}. Macht Euch keine Gedanken mehr über diese schmutzigen Bomben und Sprengstoffe, denn Ihr werdet bald über Euch selbst hinauswachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29481] = { id = 29481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.\n\nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Tränke und Transmutation nicht mehr angeboten.", sourceObjective = "Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer.", progress = "Habt Ihr die Fläschchen?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[29482] = { id = 29482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Eisen zu Gold, Wasser zu Feuer... ich kann Euch helfen, wenn Ihr ein Meister der Transmutation werden wollt.\n\nDie Ausbildung ist sehr teuer, also bringt mir eines der besten Materialien der Welt: Echtgold.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Transmutationsbeherrschung abgeschlossen habt, werden Euch Tränke und Elixiere nicht länger angeboten.", sourceObjective = "Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr das Gold?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[29506] = { id = 29506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine prickelnde Mischung", description = "Als <Alchemist/Alchemistin> habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?\n\nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.\n\nEin Gastwirt im Wald von Elwynn oder in Mulgore wird Euch genügend Saft für Eure Kreation verkaufen können.", sourceObjective = "Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.", progress = "Was macht der Mondbeerenfizz?", completion = "Eure Kreation sieht vielversprechend aus. Mit ein wenig Glück werden wir bald ein neues Lieblingsgetränk haben!\n\nIch danke Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29507] = { id = 29507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß für die Kleinen", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", sourceObjective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", progress = "Wie sieht es aus? Wollt Ihr ein paar Fossilienfragmente spenden?", completion = "Großartig! Die Kinder werden sich sehr freuen, wenn sie diese Teile \"entdecken\".", sourceObjectiveStatus = "unverified-source-field" }
quests[29508] = { id = 29508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby braucht zwei Paar Schuhe", description = "Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.\n\nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.\n\nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?", sourceObjective = "Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.", progress = "Wie geht's dem alten Mädchen?", completion = "Danke für Eure Hilfe, {name}! Hier ist die versprochene Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29509] = { id = 29509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Frosch knusprig wird", description = "Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!\n\nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?\n\nDas Mehl, in dem Ihr die Frösche wälzen müsst, bekommt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore.", sourceObjective = "Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.", progress = "Rieche ich etwa frische Knusperfrösche?", completion = "Die sind auf den Punkt gebraten, {name}. Sehr gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29510] = { id = 29510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Abfall kann nützlich sein", description = "Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, {name}. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.\n\nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?", sourceObjective = "Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.", progress = "Habt Ihr etwas Wahrsagerstaub bekommen?", completion = "Das hilft mir schon mal weiter. Wenn Ihr noch einmal helfen wollt, besucht einfach den alten Sayge, wenn der Dunkelmond-Jahrmarkt in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29511] = { id = 29511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerreparatur", description = "Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.\n\nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.", sourceObjective = "Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.", completion = "Sehr gute Arbeit. Die Panzer laufen wieder. Hier sind die versprochenen Lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29512] = { id = 29512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kratzer, Beulen, blaue Flecke", description = "Die Arbeit auf dem Dunkelmond-Jahrmarkt ist gefährlich, {name}. Unsere Arbeiter verletzen sich oft beim Aufbau, Abbau und Transport der Attraktionen.\n\nEinige der verletzten Arbeiter findet Ihr in der Nähe der Wagen. Andere wollen sich im Heilzelt behandeln lassen. Warum nehmt Ihr nicht diese Bandagen und seht, ob Ihr den verletzten Arbeitern helfen könnt?", sourceObjective = "Nehmt die Bandagen des Dunkelmond-Jahrmarkts und heilt damit 4 verletzte Schausteller.", completion = "Ich danke Euch für Eure Hilfe, {name}. Der Jahrmarkt kann nur weiterbestehen, wenn wir alle zusammenhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29513] = { id = 29513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerer Fisch im Schlafrock", description = "Wir haben gerade ein neues Gericht in unsere Speisekarte aufgenommen, den Fisch im Schlafrock. Es ist so beliebt, dass wir die Nachfrage kaum erfüllen können!\n\nIhr seht aus, als wüsstet Ihr, wie man mit einer Angel umgeht, {race}. Würdet Ihr mir bei der Aufstockung meiner Vorräte helfen?\n\nWir wollen doch all die Jahrmarktsbesucher, die etwas Neues ausprobieren wollen, nicht enttäuschen, oder?", sourceObjective = "Fangt 5 große Meeresheringe im Ozean rund um die Dunkelmondinsel.", progress = "Habt Ihr die Fische?", completion = "Genau die richtigen! Hier sind wie versprochen Eure Lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29514] = { id = 29514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilkräuter", description = "Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.\n\nMit ihnen kann man Wunden behandeln und Essen würzen.\n\nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?", sourceObjective = "Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.", progress = "Wie geht das Kräutersammeln voran?", completion = "Danke, {name}. Sobald der Dunkelmond-Jahrmarkt wieder in der Stadt ist, würde ich gern noch einmal auf Eure Hilfe zurückgreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29515] = { id = 29515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Zukunft", description = "Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.\n\nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.\n\nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Das Pergament, das Ihr dafür braucht, könnt Ihr bei jedem Handelswarenhändler im Wald von Elwynn oder in Mulgore erwerben.", sourceObjective = "Stellt aus dem Bund exotischer Kräuterprophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.", progress = "Habt Ihr die Horoskope geschrieben?", completion = "Die sehen genau wie meine aus. Ihr habt ein gutes Gespür für Details. Ich danke Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29516] = { id = 29516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarkt der Eitelkeiten", description = "Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.\n\nSeid Ihr geübt im Juwelenschleifen und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?\n\nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen fürs Juwelenschleifen bearbeitet werden, entstehen daraus wunderschöne Edelsteine.", sourceObjective = "Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde \"Edelsteine\".", progress = "Ist es Euch gelungen, Ersatzedelsteine für den Schmuck unserer Künstler zu schleifen?", completion = "Sehr gute Arbeit, {name}. Ihr seid wirklich talentiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29517] = { id = 29517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begehrte Preise", description = "Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.\n\nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch gern ein Set geben. Ihr werdet einige Teile bei einem Handelswarenhändler wie Faldar Weidenschatten erwerben müssen, aber sie sind nicht teuer.\n\nWollt Ihr mir helfen?", sourceObjective = "Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.", progress = "Habt Ihr die Preise hergestellt?", completion = "Sehr gute Arbeit! Die Preise sehen genauso aus wie die anderen. Ich danke Euch für Eure Hilfe.\n\nWenn Ihr noch einmal helfen wollt, dann sucht mich auf, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29518] = { id = 29518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", sourceObjective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", progress = "Habt Ihr Schrott gefunden? Der Platz ist voll davon.", completion = "Das ist eine Menge Schrott. Ich danke Euch für Eure Hilfe. Damit werde ich viele Panzer reparieren können.\n\nHier, nehmt dies als kleine Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29519] = { id = 29519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerbt meine Häute", description = "Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.\n\nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.", sourceObjective = "Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.", completion = "Ich danke Euch für Eure Hilfe, {name}. Ich werde Euch in guter Erinnerung behalten.\n\nUnd wenn Ihr möchtet, könnt Ihr mir gern wieder helfen, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29520] = { id = 29520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner, überall Banner!", description = "Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.\n\nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf dem Lagerplatz des Jahrmarkts.\n\nEs fehlen noch einige Teile, doch die solltet Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben können.", sourceObjective = "Stellt mit einem groben Faden sowie rotem und blauem Farbstoff zusammen mit dem Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf dem Lagerplatz des Jahrmarkts.", completion = "Danke für Eure Hilfe. Ihr seid recht begabt mit Nadel und Faden. Wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist, könnt Ihr uns gern wieder helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29527] = { id = 29527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg im Bollwerk", description = "Wachhabender Gargolmar und Vazruden der Herold haben das Kommando über die Verteidigung des Bollwerks.\n\nWenn Ihr sie ausschaltet, werden die Soldaten in Panik geraten.\n\nTötet sie und bringt mir einen Beweis für Eure Tat, damit die Invasion beginnen kann!", sourceObjective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Steingardist Stok'ton.", progress = "Diese Mission hängt von Eurem Erfolg ab, {name}.", completion = "Ohne ihre Anführer sollten die Truppen in Panik geraten.\n\nAber es geht hier um mehr als die Beseitigung einiger Wachen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29528] = { id = 29528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg im Bollwerk", description = "Die Verteidigung der Höllenfeuerzitadelle hängt in erster Linie vom Bollwerk ab, das als eine Art Frühwarnsystem dient.\n\nBeseitigt Wachhabenden Gargolmar und Vazruden den Herold. Ohne sie wird die Eroberung des Bollwerks ein Kinderspiel sein.", sourceObjective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Vorhutsspäher Chadwick.", progress = "Wart Ihr erfolgreich? Von dieser Mission hängt sehr viel ab, {name}.", completion = "Ich wusste, dass ich auf Euch zählen kann!\n\nIhre Streitkräfte sind nun führerlos. Die Invasion kann beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29529] = { id = 29529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Zitadelle", description = "Einer unserer Späher berichtet, er habe irgendwo im Bollwerk einen Agenten der Brennenden Legion gesehen. Wenn das stimmt, laufen wir Gefahr, dass die Ehrenfeste von zwei Seiten angegriffen wird!\n\nWenn Ihr diesen Teufel findet, dann bringt ihn um.", sourceObjective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Vorhutsspäher Chadwick.", progress = "Habt Ihr dort drinnen Dämonen entdeckt?", completion = "Dann ist es also wahr. Die Höllenorcs und die Brennende Legion arbeiten auf irgendeine Weise zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29530] = { id = 29530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Zitadelle", description = "Einer unserer Späher hat unangenehme Neuigkeiten überbracht. Wir haben einen mächtigen Agenten der Brennenden Legion im Bollwerk entdeckt!\n\nBringt diesen Dämon um, bevor er seinen Vorgesetzten von unseren Plänen berichten kann.", sourceObjective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Steingardist Stok'ton.", progress = "Konntet Ihr die üble Kreatur beseitigen?", completion = "Gut gemacht. Wir brauchen die Zeit, die Ihr uns erkauft habt, um der Verbindung zwischen Höllenorcs und brennender Legion nachzugehen. Eure Taten haben vielleicht Hunderten das Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29535] = { id = 29535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie bluten!", description = "Der Schöpfer erzeugt neue Höllenorcs, indem er ihnen Dämonenblut injiziert.\n\nMeine Vorgesetzten glauben, dass sich der Prozess rückgängig machen lässt, aber um das auszuprobieren, benötigen wir Proben ihres Blutes und die Injektionsspritze des Schöpfers.", sourceObjective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Caza'rez.", progress = "Ihr seid zurück und sogar lebendig! Gut gemacht. Besser als alle anderen bis jetzt.", completion = "Diese Phiolen könnten das Ende der Höllenorcs einläuten. Ich hoffe, dass Ihr versteht, wie wichtig das für unseren Feldzug wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[29536] = { id = 29536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Zorns", description = "Wir wissen, dass die Höllenorcs ihren Fokus erhöhen, indem sie Orcs Dämonenblut injizieren.\n\nBegebt Euch tief in diese unheiligen Hallen und findet heraus, was dort geschieht. Wir können es erst riskieren, eine Armee hineinzuschicken, wenn wir genau wissen, was uns erwartet.", sourceObjective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Caza'rez.", completion = "<Ihr erzählt Caza'rez alles, was Ihr im Blutkessel gesehen habt.>\n\nWenn sie das den braunen Orcs der Mag'har antun können, dann sind auch wir in Gefahr! Wir müssen vorsichtig sein, sonst werden alle in Thrallmar zu hirnlosen Bestien.", sourceObjectiveStatus = "unverified-source-field" }
quests[29537] = { id = 29537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht, Lücke!", description = "Im ganzen Blutkessel gibt es nur ein Gebiet, das unsere Seher trotz aller Mühen nicht erreichen können.\n\nDiese \"Lücke\", wie sie es nennen, ist recht groß. Dort wird bestimmt Magtheridon gefangen gehalten.\n\nIhr müsst die Ursache dieser Störungen finden und vernichten.", sourceObjective = "Tötet Keli'dan den Zerstörer und kehrt zu Caza'rez zurück.", completion = "Die Störungen haben nachgelassen, aber wir können das Gebiet immer noch nicht sehen. Wir werden der Sache weiter nachgehen. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29538] = { id = 29538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie bluten!", description = "Mit Dämonenblut und einer speziellen Spritze verwandelt der Schöpfer braune und grüne Orcs in rote. Wir würden uns das Blut gern ansehen und damit herumspielen, bis es Orcs aller Farben in harmlose, friedliche Ochsen verwandelt.\n\nBringt mir einige Proben ihres Blutes, damit wir anfangen können. Und vergesst die Spritze nicht!", sourceObjective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Gunny.", progress = "Habt Ihr das Blut, Prinzessin? Wir haben Euch bestimmt nicht darum gebeten, weil es unwichtig ist.", completion = "Verdammt beeindruckend! Damit steigt Ihr auf Platz acht meiner Lieblingspersonen in den qualmenden Ruinen dieses bemitleidenswerten Planeten auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[29539] = { id = 29539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Zorns", description = "Hat sich gezeigt, dass die Eierköpfe in der Ehrenfeste nicht viel von diesem Ort hier sehen können. Lügende, faule Magier sind das, nichts weiter.\n\nWie dem auch sei, wir wissen nicht genau, was hier vorgeht. Also werdet Ihr das herausfinden!", sourceObjective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Gunny.", completion = "<Ihr erzählt Gunny alles, was Ihr im Blutkessel gesehen habt.>\n\nIhr habt doch auch Beute für den alten Gunny, oder?\n\nNein, Ihr habt natürlich recht. Ich schulde Euch eine Belohnung für Eure harte Arbeit, auch wenn Ihr ohne mich überhaupt nicht hineingegangen wäret.", sourceObjectiveStatus = "unverified-source-field" }
quests[29540] = { id = 29540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zerstörer", description = "Die verstecken hier irgendwo so einen großen, alten Dämon, hab ich gehört. Und da gibt's auch einen Orc, der darauf achten soll, dass er bleibt, wo er hingehört.\n\nEin Orc ist ein Orc, und Orcs werden umgebracht, richtig? Ist egal, was er tut oder getan hat, einer weniger schadet nie.", sourceObjective = "Tötet Keli'dan den Zerstörer und kehrt zu Gunny zurück.", completion = "Wirklich? Ihr wollt eine Belohnung, weil Ihr einen Orc umgebracht habt? So wie in Ruhm und Reichtum und edle Reittiere?\n\nZu meiner Zeit war es Belohnung genug, einen Orc töten zu DÜRFEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[29542] = { id = 29542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Zitadelle", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden Thrallmar überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf den Weg nach Westen zum Höllenfeuerbollwerk und sprecht mit Steingardist Stok'ton. Die Geheimmission, die er leitet, wird der Horde den Weg in die Zitadelle ebnen.", sourceObjective = "Sprecht mit Steingardist Stok'ton im Höllenfeuerbollwerk.", completion = "Schädelbrecher ist nicht gerade freundlich, aber er weiß, was er tut. Und für Euch gibt es auch genug Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29543] = { id = 29543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Zitadelle", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden die Ehrenfeste in Kürze überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf nach Westen zum Höllenfeuerbollwerk und sprecht dort mit Vorhutsspäher Chadwick. Die Mission, die er leitet, wird der Allianz den Weg in die Zitadelle ebnen.", sourceObjective = "Sprecht mit Vorhutsspäher Chadwick im Höllenfeuerbollwerk.", completion = "Altumus ist wirklich ein Juwel. Aber wir werden hier nur lebend herauskommen, wenn wir im Bollwerk siegreich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29563] = { id = 29563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen im Kampf", description = "Ihr müsst mir helfen! Wir wurden ausgesandt, um die verschiedenen Bereiche des Kessels zu erkunden, aber das war vor einiger Zeit und meine Freunde sind noch nicht zurückgekehrt.\n\nBitte findet heraus, ob ihnen etwas zugestoßen ist. Naturalist Biss und Jäter Gründaum sind in diese Richtung gegangen.", sourceObjective = "Findet heraus, was Naturalist Biss und Jäter Gründaum zugestoßen ist. Kehrt dann zu Behüterin Jhang zurück.", completion = "Der Verlust des Lebens... so schmerzhaft.\n\n<Behüterin Jhang seufzt.>\n\nDanke, {name}. Wenn wir alle wieder vereint sind, werden uns die Naga nichts anhaben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29564] = { id = 29564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der betrogene Bruder", description = "Anfangs gelang es meinem Dorf, den Angriffen der Naga auszuweichen. Wir hätten es bis nach Nagrand geschafft, wenn mein Bruder nicht gewesen wäre. Mit unseren Seelen erkaufte er sich seine Freiheit.\n\nNun arbeitet er hier als Sklavenaufseher und peitscht seine eigenen Brüder aus, bis ihre Rücken bluten. Dafür muss Mennu bezahlen, {race}.", sourceObjective = "Tötet Mennu den Verräter und kehrt zu Nahuud zurück.", completion = "Mennus Tod kann die Wunden meiner Familie und Freunde nicht heilen, aber wenigstens können sie den Rest ihres Lebens in Freiheit verbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29565] = { id = 29565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Pudels Kern", description = "Nahuud hat mir erklärt, zwei mächtige Wesen, Rokmar der Zerquetscher und Quagmirran, seien als erste von den Naga nach deren Ankunft versklavt worden. Sie haben bei der Unterwerfung vieler Völker in den Zangarmarschen geholfen.\n\nIch tue das sehr ungern, aber ich muss Euch bitten, sie zu töten.", sourceObjective = "Bringt die Klaue des Eindringlings und das Auge des Sklaventreibers zu Behüterin Jhang.", progress = "Habt Ihr sie getötet?", completion = "Ich bin froh, dass ihr Geist nun frei ist. Ich wünschte, das gleiche könnte man von den anderen ihrer Art sagen.\n\nEs gibt noch viel zu tun, vor allem in den anderen Teilen des Echsenkessels.", sourceObjectiveStatus = "unverified-source-field" }
quests[29566] = { id = 29566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Expedition", description = "Die Sümpfe sind wunderschön, findet Ihr nicht? Abgesehen natürlich von den Naga, die das Wasser abpumpen.\n\nIch habe eine kleine Expedition zum Echsenkessel geschickt. Sie sollte die Naga beobachten, aber bis jetzt ist niemand zurückgekehrt. Ich mache mir Sorgen um sie.\n\nWürdet Ihr Euch zu den Sklavenunterkünften unterhalb des Schlangensees begeben und nach Behüterin Jhang suchen?", sourceObjective = "Sprecht mit Behüterin Jhang in den Sklavenunterkünften.", completion = "Was macht Ihr denn hier unten? Ihr könnt doch sehen, dass es hier nicht gerade sicher ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[29567] = { id = 29567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Mutter", description = "Die Fungusgiganten greifen zwar heutzutage mein Volk an, aber die Marschenläufer haben bereits mehr Unschuldige auf dem Gewissen als alle anderen Kreaturen, die ich kenne. Sie sind seit Urzeiten unser Feind.\n\nIhre Brutmutter, die man auch Schattenmutter nennt, lebt in den Tiefen dieses Sumpfes. Wenn es Euch gelingen sollte, sie zu vernichten und mir ihr Gehirn als Beweis zu bringen, würde ich noch meinen Enkeln von Eurer ruhmreichen Tat erzählen.", sourceObjective = "Bringt das Gehirn der Schattenmutter zu T'shu.", progress = "Ihr seid zurück. Heißt das die Schattenmutter ist nicht mehr?", completion = "Die Schattenmutter ist tot! Normalerweise schwelge ich ja nicht in solchen Gemetzeln, aber der Schmerz, den die große Mutter und ihre Brut über Jahrhunderte meinem Volk zugefügt haben, ist unaussprechlich.\n\nIch bin Euch auf ewig dankbar, mutiger {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29568] = { id = 29568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein notwendiges Übel", description = "Hungarfenn und Quagmirran herrschten einst gemeinsam über die Fungusgiganten. Seit Quagmirrans Tod lastet diese Verantwortung allein auf Hungarfenns Ranken.\n\nWir müssen den Riesen töten, bevor er versklavt und als Waffe gegen uns eingesetzt werden kann.", sourceObjective = "Tötet Hungarfenn und kehrt zu Naturalist Biss zurück.", completion = "Ihr habt den Zangarmarschen an diesem Tag einen großen Gefallen erwiesen, {name}. Die Fungusgiganten sind zwar von Natur aus angriffslustig, aber sie sind ein wichtiger Teil des Ökosystems.", sourceObjectiveStatus = "unverified-source-field" }
quests[29570] = { id = 29570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Expedition", description = "Die restlichen Mitglieder meiner Expedition sind irgendwo hier drinnen. Wir brauchen das Wissen, das sie erlangt haben, und die Fähigkeiten, die sie besitzen, sonst werden wir die Naga niemals schlagen.\n\nSucht nach Erdbinder Rayge und Windrufer Klaue und stellt sicher, dass es ihnen gut geht.", sourceObjective = "Findet heraus, was mit Erdbinder Rayge und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang zurück.", completion = "Bald werden wir wieder vereint sein, und das habe ich Euch zu verdanken!\n\nWir werden die Naga schneller besiegen, als Ihr denkt. Sie haben keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
